export type QuizItem = [string, string[], string, string] | [string, string[], string, string, string]

const S = '<' + 'script setup>'

export const Q: QuizItem[] = [
    ['ok 从 true 变为 false，再变回 true。哪一句正确？', ['A 的 <p> 被删除后重新创建；B 的 <p> 一直存在，只改 display', 'A 的 <p> 一直存在，只改 display；B 的 <p> 被删除后重新创建', '两个 <p> 都被删除后重新创建，v-show 只是 v-if 的简写', '两个 <p> 都一直存在；v-if 为假时加 hidden 属性'], 'v-if 为假时不创建元素，只留一个注释节点占位。v-show 总是创建元素，用 display: none 隐藏它。第二项把两者说反了。第三项错在 v-show 不删除元素。第四项错在 v-if 为假时 DOM 中没有这个元素。Vue 也不使用 hidden 属性。', 'template',
      '<p v-if="ok">A</p>\n<p v-show="ok">B</p>'],
    ['下面哪一个插值可以通过编译？', ['{{ ok ? \'是\' : \'否\' }}', '{{ if (ok) \'是\' }}', '{{ let n = count + 1 }}', '{{ for (x of list) x }}'], '插值中只能写一个表达式。判断方法：这段代码可以放在 return 后面。三元运算是表达式，所以可以使用。if、let 和 for 都是语句，编译器报错。需要多行逻辑时，写一个计算属性。', 'template'],
    ['<input v-model="text"> 展开后等于哪种写法？', [':value="text" @input="text = $event.target.value"', ':value="text" @change="text = $event.target.value"', ':modelValue="text" @update:modelValue="text = $event"', ':value="text" @input="text = $event"'], '用在原生 input 上时，v-model 绑定 value，并监听 input 事件。v-model 还处理输入法：拼音阶段不更新数据。@change 是 .lazy 修饰符的行为，失去焦点时才更新。modelValue 和 update:modelValue 用在组件上。原生 input 事件的 $event 是事件对象，不是输入的文字。', 'template'],
    ['点击“提交”按钮后，会发生什么？', ['save 运行，页面不刷新', 'save 运行，然后页面刷新', '页面刷新，save 不运行', 'save 运行，事件不再冒泡'], '.prevent 调用 event.preventDefault()。所以浏览器不提交表单，页面不刷新。save 照常运行。没有 .prevent 时，save 运行后页面刷新。阻止冒泡的是 .stop，不是 .prevent。', 'template',
      '<form @submit.prevent="save">\n  <input v-model="name">\n  <button>提交</button>\n</form>'],
    ['评论来自用户输入。用 <div v-html="comment"> 显示评论。有什么风险？', ['评论中 <img onerror> 等代码会运行', 'Vue 会转义 v-html，所以没有风险', '评论中的标签显示为文字，不被解析', '只有 <' + 'script> 会运行，删除它即可'], 'v-html 不转义内容，直接设置 innerHTML。浏览器不运行 innerHTML 中的 <' + 'script>。但是浏览器会运行 onerror 等事件属性。所以只删除 <' + 'script> 不安全。显示为文字的是 {{ }}，不是 v-html。用户输入要用 {{ }} 显示，或先用 DOMPurify 等库清理。', 'template'],
    ['下面的代码输出什么？', ['0 1', '1 1', '0 0', '报错'], '解构只读取一次，count 得到数字 0。之后修改 state.count，count 不变。所以输出 0 1。第二项以为解构保持连接。第三项以为 state.count++ 没有生效。解构普通值不会报错。需要保持连接时，使用 toRefs(state)。', 'refs',
      'const state = reactive({ count: 0 })\nlet { count } = state\nstate.count++\nconsole.log(count, state.count)'],
    ['r = shallowRef({ n: 1 })。执行 r.value.n++ 后，结果是什么？', ['n 变为 2，页面不更新', 'n 变为 2，页面也更新', 'n 仍是 1，页面不更新', 'n 变为 2，下一帧更新'], 'shallowRef 只跟踪 .value 的替换，不代理内部对象。r.value.n++ 修改了普通对象，所以 n 是 2。但是没有触发更新，页面不变。第二项以为 shallowRef 也深层跟踪。第三项错在对象本身被修改了。Vue 不会延迟到下一帧补上更新。要更新页面，替换 r.value 或调用 triggerRef(r)。', 'refs'],
    ['下面代码中，① 和 ② 分别输出什么？', ['① 0　② 6 1', '① 2　② 6 3', '① 0　② 6 2', '① 2　② 6 2'], 'computed 是惰性的。没有读取时，getter 不运行，所以 ① 是 0。读取 double.value 时，getter 运行一次，得到 6。所以 ② 是 6 1。以为 ① 是 2 的选项，误认为修改依赖会立即计算。6 2 和 6 3 也来自同一个误解。', 'computed',
      'const a = ref(1)\nlet runs = 0\nconst double = computed(() => { runs++; return a.value * 2 })\na.value = 2\na.value = 3\nconsole.log(runs)               // ①\nconsole.log(double.value, runs) // ②'],
    ['id 还没有改变。下面的代码输出什么？', ['effect 1、sync', 'watch 1、sync', 'sync、effect 1', 'sync、watch 1'], 'watchEffect 创建时立即同步运行一次，并收集依赖。所以先输出 effect 1。watch 默认不立即运行，id 改变后才运行。所以没有 watch 1，包含 watch 1 的两项都错。watchEffect 的第一次运行不进入队列。所以 effect 1 在 sync 之前。给 watch 加 { immediate: true } 才会立即运行。', 'computed',
      'const id = ref(1)\nwatch(id, v => log(\'watch \' + v))\nwatchEffect(() => log(\'effect \' + id.value))\nlog(\'sync\')'],
    ['子组件要改变父组件传入的 prop，并让父组件也得到新值。哪种做法正确？', ['emit 一个事件，父组件修改数据', '直接给 props.x 赋一个新值', '把 props.x 复制到 ref，再修改', '用 watch 侦听 props.x 并修改'], 'Vue 使用单向数据流：数据的所有者修改数据。子组件发出事件，父组件修改。v-model 也这样工作。props 是只读的，开发环境中直接赋值无效并显示警告。复制到 ref 只改变子组件的副本，父组件得不到新值。watch 中修改 props 仍然是给只读对象赋值。', 'comm'],
    ['开发环境中，这段子组件代码运行 onInput 后，结果是什么？', ['赋值无效，开发环境显示警告', '赋值成功，父组件的数据也改变', '赋值成功，只有子组件显示新值', 'e.target 为空，抛出错误'], 'props 是只读的代理。赋值不生效，开发环境显示警告。所以父组件和子组件都不显示新值。e.target 是触发事件的 input 元素，不为空。生产构建跳过这个检查：赋值会暂时改变子组件看到的值，父组件下次更新时又覆盖它。所以不要依赖这种赋值。修复：调用 emit(\'update:modelValue\', e.target.value)，或使用 3.4+ 的 defineModel()。', 'comm',
      S + '\nconst props = defineProps([\'modelValue\'])\nfunction onInput(e) {\n  props.modelValue = e.target.value\n}\n<\/script>'],
    ['父组件写 <List v-slot="{ item }">。item 来自哪里？', ['子组件 List 的 <slot> 传出', '父组件 setup 中的同名变量', 'List 的 props 中的 item', '父组件 v-for 的循环变量'], '这是作用域插槽。子组件写 <slot :item="it">，把数据作为 slot 的属性传出。父组件在 v-slot 中接收并解构。数据来自子组件，所以不是父组件的变量，也不是父组件的 v-for。List 的 props 是父组件传给 List 的数据，方向相反。', 'comm'],
    ['1 秒后，后代组件显示什么？', ['仍然显示 light', '变为显示 dark', '先空白，再显示 dark', '空白，控制台有警告'], 'provide 传递的是当时的值，也就是字符串 \'light\'。之后给变量 theme 赋新值，不影响已经传出的字符串。所以后代组件仍然显示 light。provide 和 inject 都成功，所以不会空白，也没有警告。要让后代收到新值，provide 一个 ref，然后修改它的 .value。', 'comm',
      '// 祖先组件 setup\nlet theme = \'light\'\nprovide(\'theme\', theme)\nsetTimeout(() => { theme = \'dark\' }, 1000)\n// 后代组件：const theme = inject(\'theme\')\n// 后代模板：{{ theme }}'],
    ['日志的输出顺序是什么？', ['Ps Cs C P', 'Ps P Cs C', 'Cs Ps C P', 'Ps Cs P C'], '父组件的 setup 先运行。父组件渲染时创建子组件，所以子组件的 setup 第二个运行。子组件先挂载完成，父组件最后挂载完成。以为父组件先挂载的选项，忽略了父组件要等子组件的 DOM 准备好。子组件的 setup 不可能先于父组件运行。', 'lifecycle',
      '// Parent 的模板：<Child />\n// Parent setup：log(\'Ps\')；onMounted(() => log(\'P\'))\n// Child  setup：log(\'Cs\')；onMounted(() => log(\'C\'))'],
    ['setup 中写 setTimeout(() => onMounted(fn), 0)。结果是什么？', ['fn 不运行，开发环境显示警告', '组件挂载后，fn 正常运行', 'fn 在回调中立即运行一次', 'fn 注册到根组件上'], '注册钩子需要当前组件实例。只有 setup 同步运行时，当前实例才有值。setTimeout 的回调运行时，setup 已经结束，当前实例为 null。所以钩子没有注册，fn 不运行。Vue 不会把它改为立即运行，也不会注册到其他组件。', 'lifecycle'],
    ['setup 顶层同步调用 useData()，没有 await。fn 会运行吗？', ['不运行，因为没有当前实例', '运行，组件挂载后运行一次', '运行，fetch 完成后立即运行', '运行两次：挂载时和 fetch 后'], 'useData 中的 await 让后面的代码在微任务中运行。这时 setup 已经结束，当前实例为 null，onMounted 没有注册。只有 ' + S + ' 顶层的 await 是例外。编译器在那里用 withAsyncContext 恢复当前实例。修复：在 await 之前调用 onMounted。', 'composables',
      'async function useData() {\n  const res = await fetch(\'/api\')\n  onMounted(fn)\n}'],
    ["组件被 <KeepAlive> 缓存。切换到另一个组件时，被缓存的组件运行哪个钩子？", ["onDeactivated","onUnmounted","onBeforeUnmount","onActivated"], "KeepAlive 不卸载缓存的组件。它把 DOM 移到一个隐藏的容器中，并运行 onDeactivated。组件没有卸载，所以 onBeforeUnmount 和 onUnmounted 都不运行。onActivated 在组件再次显示时运行。", "builtins"],
    ["弹窗组件放在 <Teleport to=\"body\"> 中。哪一句正确？", ["DOM 移到 body，组件关系不变","组件变成根组件，不能 inject","DOM 留在原处，只提高了 z-index","父组件不能再监听它的 emit"], "Teleport 只改变 DOM 的位置。组件树不变，所以 props、emit、provide 和 inject 照常工作。DOM 真的移到了 body 中，不只是改变层级。组件的事件不靠 DOM 冒泡传递，所以 DOM 位置不影响 emit。", "builtins"],
    ["show 从 true 变为 false。页面上的 <p> 会怎样？", ["在下一帧被删除，没有离开动画","用 0.3 秒向右滑出，然后被删除","一直留在页面上，因为没有离开动画","报错：缺少 slide-leave-active 类"], "Vue 只负责在离开时添加 slide-leave-from、slide-leave-active、slide-leave-to 这几个类，动画本身由 CSS 决定。样式里没有任何离开规则，元素上没有 transition，Vue 检测不到动画，所以不等待，下一帧就把元素删除。进入规则不会用在离开上。没有离开规则不会报错，元素也不会留下来。", "builtins",
      "<Transition name=\"slide\">\n  <p v-if=\"show\">你好</p>\n</Transition>\n\n/* 样式里只有进入的规则 */\n.slide-enter-active { transition: transform 0.3s; }\n.slide-enter-from { transform: translateX(100%); }"],
    ["点击按钮后，show 变为 false。800 毫秒后页面上的 <p> 怎样？", ["还在页面上，因为 done 一直没有被调用","已被删除，Vue 默认 300 毫秒后删除","已被删除，因为 :css=\"false\" 让 Vue 立即删除","已被删除，show 为 false 时 v-if 总是立即生效"], "写了 @leave 并声明了 done 参数时，Vue 等你调用 done 才把元素删除。:css=\"false\" 只是让 Vue 不去找 CSS 类名，不会让它立即删除。Vue 没有默认的 300 毫秒超时。v-if 在 Transition 里的删除会被延迟到离开动画结束。修复：动画结束后调用 done()，例如 el.animate(…).onfinish = done。", "builtins",
      "<Transition :css=\"false\" @leave=\"onLeave\">\n  <p v-if=\"show\">你好</p>\n</Transition>\n\nfunction onLeave(el, done) {\n  // 忘了在动画结束时调用 done\n}"],
    ["items 从 ['A', 'B', 'C'] 变为 ['C', 'A', 'B']。页面上发生了什么？", ["三个 <li> 都留在原位，只是文字变了，没有移动动画","C 向上移动到第一行，A 和 B 各下移一行","C 的 <li> 被删除，在第一行重新创建","报错：TransitionGroup 的 key 不能是数字"], "key 是 0、1、2，数据变化前后每个 key 对应的元素没有变，Vue 认为三个元素都还在原位，只更新它们的文字。元素没有改变位置，所以不添加 move 类，也没有移动动画。要让元素跟着数据移动，key 要用数据自己的 id。key 可以是数字，所以不会报错。", "builtins",
      "<TransitionGroup name=\"list\" tag=\"ul\">\n  <li v-for=\"(x, i) in items\" :key=\"i\">{{ x }}</li>\n</TransitionGroup>"],
    ['v-click-outside 在 mounted 中调用 document.addEventListener。元素卸载后会怎样？', ['监听仍在，点击时回调仍运行', 'Vue 自动删除这个监听', '浏览器删除元素时删除监听', '监听仍在，但回调不再运行'], '监听添加在 document 上，不属于这个元素。Vue 和浏览器都不知道要删除它。所以监听一直存在，每次点击都运行回调，这是内存泄漏。修复：把监听函数保存在 el 上，在 unmounted 中调用 removeEventListener。', 'directives'],
    ['<input v-focus:top.once="x">。binding.arg 和 binding.modifiers 分别是什么？', ["'top' 和 { once: true }", "'once' 和 { top: true }", "'top' 和 ['once']", "'top.once' 和 {}"], '冒号后面是参数，所以 arg 是 \'top\'。点后面是修饰符。modifiers 是一个对象，不是数组，所以是 { once: true }。第二项把参数和修饰符说反了。点号不属于参数，所以 arg 不是 \'top.once\'。等号后面表达式的值是 binding.value。', 'directives'],
    ['表单中的错误信息最适合用什么得到？', ['用 computed 从字段的值计算', '在每个 input 事件中设置 ref', '用 watch 侦听字段，写入 ref', '在 onUpdated 中计算后写入 ref'], '错误信息是派生数据。computed 让错误和字段的值总是一致。在 input 事件中手动设置，容易漏掉 reset 等其他修改途径。watch 能工作，但是多了一份要同步的状态。onUpdated 在渲染之后运行，写入 ref 会再渲染一次。', 'forms'],
    ['Child 在 setup 中抛出错误。Parent 和 Grand 都有 onErrorCaptured，都返回 undefined。顺序是什么？', ['Parent、Grand，最后 errorHandler', 'errorHandler，然后 Parent、Grand', 'Grand、Parent，最后 errorHandler', '只运行 Parent 的 onErrorCaptured'], '错误从出错的组件向上传递：先到最近的祖先 Parent，再到 Grand。最后到达 app.config.errorHandler。所以 errorHandler 最后运行，祖先的顺序是从近到远。只有 onErrorCaptured 返回 false 时，错误才停止传递。', 'app'],
    ["Vue 3 的响应式系统用什么拦截对象的读写？", ["Proxy 和 Reflect","Object.defineProperty","脏检查：定时比较全部数据的新旧值","MutationObserver"], "Proxy 可以拦截 get、set、has、deleteProperty 和 ownKeys。所以新增属性和数组下标也能被跟踪。Vue 2 使用 defineProperty，它不能拦截新增属性。脏检查是 AngularJS 的做法。MutationObserver 观察 DOM，不观察 JavaScript 对象。", "reactivity"],
    ["副作用函数每次重新运行前，为什么要清理旧的依赖？", ["分支改变后，不再读取的属性不应触发它","防止同一个属性被重复记录多次","Proxy 每次只允许一个 get 拦截","旧依赖会让 computed 缓存失效"], "例如 show ? a : b。show 变为假后，函数不再读取 a。不清理时，修改 a 仍然触发一次无用的运行。依赖保存在 Set 中，重复记录本来就会被去重。Proxy 没有拦截次数的限制。清理和 computed 的缓存无关。", "reactivity"],
    ["runs 最后是多少？", ["2","3","1","4"], "第一次运行时，读取 ok 和 a，runs 为 1。ok 改变后再运行一次，这次读取 ok 和 b，runs 为 2。旧依赖 a 已被清理，所以修改 a 不触发运行。选 3 是忽略了依赖清理。选 1 是以为 watchEffect 只运行一次。", "reactivity",
      "const state = reactive({ ok: true, a: 1, b: 2 })\nlet runs = 0\nwatchEffect(() => { runs++; state.ok ? state.a : state.b })\nstate.ok = false\nawait nextTick()\nstate.a = 10\nawait nextTick()\nconsole.log(runs)"],
    ["Vue 3.5 中，读取 computed 时，Vue 怎样确定是否需要重新计算？", ["比较依赖的版本号，未变就用缓存","每次读取都重新运行 getter","把依赖的值序列化后比较","比较 getter 两次的返回值"], "每个 Dep 有一个版本号。computed 保存上次读到的版本号。所有版本号都相同时，Vue 不运行 getter。每次都运行就没有缓存了。序列化（例如 JSON.stringify）太慢，而且不能处理所有类型。比较返回值必须先运行 getter。返回值只用于决定 computed 自己的版本号是否改变。", "reactivity"],
    ["下面的代码运行完，getter 一共运行了几次？", ["2","1","3","4"], "创建 effect 时读取 sum，getter 运行第 1 次。`a.value = 1` 是相同的值，不触发，version 不变。`b.value = 2` 让 b 的 version 加 1，sum 被通知，effect 运行前先刷新 sum：getter 运行第 2 次，和变成 3。第二次 `b.value = 2` 又是相同的值，什么都不发生。所以是 2。选 3 的人把相同值的赋值也算成一次改变。选 1 的人以为 computed 只在创建时算一次。", "reactivity",
      "const a = ref(1), b = ref(1)\nlet runs = 0\nconst sum = computed(() => { runs++; return a.value + b.value })\neffect(() => sum.value)\na.value = 1\nb.value = 2\nb.value = 2\nconsole.log(runs)"],
    ["下面三个表达式的结果分别是什么？", ["1　1　true","1　undefined　false","1　1　false","undefined　1　true"], "reactive 的 Map 在 get、has 里同时用传入的 key 和 toRaw(key) 查找。`key` 本身是原始对象，一次就找到。`reactive(key)` 是代理，先用代理查不到，再用原始对象查，也找到了，所以 get 得到 1，has 得到 true。第二项以为代理和原始对象是两把不同的钥匙。这是数组 includes 的同一类处理，实现在 collectionHandlers 里。", "reactivity",
      "const key = {}\nconst m = reactive(new Map())\nm.set(key, 1)\nconsole.log(m.get(key), m.get(reactive(key)), m.has(reactive(key)))"],
    ["effect 打印了哪些值？（忽略控制台警告）", ["1、2，之后 ro.n 仍是 2","1、2、3","1，因为 readonly 不收集依赖","1、3，因为最后一次赋值生效"], "readonly 代理的 get 自己不收集依赖，但 `readonly(state)` 的 target 是 reactive 代理。读取 `ro.n` 时，`Reflect.get(target, …)` 经过内层 reactive 代理，内层收集依赖。所以 `state.n = 2` 会让 effect 重新运行，打印 2。`ro.n = 3` 被只读 handler 拦下：开发环境警告，不修改数据，所以不会有 3。选第三项的人以为只读对象永远不响应。只有对一个普通对象调用 readonly 时，才没有任何东西会通知它。", "reactivity",
      "const state = reactive({ n: 1 })\nconst ro = readonly(state)\neffect(() => console.log(ro.n))\nstate.n = 2\nro.n = 3"],
    ["一次修改同时通知两个 effect。输出顺序是什么？", ["A0 B0 A1 B1","A0 B0 B1 A1","B0 A0 A1 B1","A0 B0 A1"], "创建时按顺序运行，输出 A0、B0。`s.value = 1` 触发 s 的 Dep，两个订阅者都被通知，在批结束时按订阅顺序运行：先 A，再 B。结果是 A1、B1。第二项以为通知顺序就是运行顺序。第四项忘了 B 也读取了 s。", "reactivity",
      "const s = ref(0)\neffect(() => log('A' + s.value))\neffect(() => log('B' + s.value))\ns.value = 1"],
    ["effect 创建后，外部再执行 `state.n = 10`。runs 和 state.n 最后分别是多少？", ["2 和 11","1 和 1","无限循环","2 和 10"], "创建时运行第 1 次：先读 n 再写 n，副作用函数修改自己读取的数据，不会触发自己，所以不会循环，n 变成 1。`state.n = 10` 是外部写入，effect 读过 n，所以运行第 2 次，`n++` 把 10 加成 11。第二项以为之后的修改不会触发它。第三项忘了触发时跳过正在运行的副作用函数。第四项忘了第 2 次运行里还有一次 `n++`。", "reactivity",
      "const state = reactive({ n: 0 })\nlet runs = 0\neffect(() => { runs++; state.n++ })\nstate.n = 10\nconsole.log(runs, state.n)"],
    ["effect 打印了哪些值？", ["false、true","false","true","false、false"], "真实的 reactive 还拦截 `has`，`'a' in s` 会收集依赖，新增属性 a 触发它，所以先打印 false，再打印 true。第二项以为 `in` 不是读取。迷你版只拦截 get、set、deleteProperty，没有 `has`，在迷你版里答案就是第二项。", "reactivity",
      "const s = reactive({})\neffect(() => console.log('a' in s))\ns.a = 1"],
    ["两个 effect 各读取一个 computed。n 从 1 变成 2，各运行几次（含创建时那一次）？", ["A 两次，B 一次","A 一次，B 一次","A 两次，B 两次","A 一次，B 两次"], "B 读取的 computed 返回布尔值，n 从 1 到 2 仍是 true，值没变，computed 的版本号不变，B 不运行。A 读取的 computed 每次返回一个新对象，`hasChanged` 比较引用，新对象和旧对象不同，版本号加 1，A 运行第 2 次。需要避免这种多余的更新时，让 computed 返回基本值，或者复用上一次的对象。", "reactivity",
      "const n = ref(1)\nconst a = computed(() => ({ big: n.value > 0 }))\nconst b = computed(() => n.value > 0)\neffect(() => a.value)   // A\neffect(() => b.value)   // B\nn.value = 2"],
    ["两个 effect 都在里面调用 push。运行后 `list.length` 是多少？", ["2","无限循环，栈溢出","4","1"], "push 内部先读 length 再写 length。Vue 在 push 期间暂停依赖收集，所以 effect 不会订阅 length，两个 effect 互不触发，各运行一次，长度是 2。没有暂停收集的话，一个 effect 的 push 会触发另一个，另一个又触发它，无限循环。", "reactivity",
      "const list = reactive([])\neffect(() => { list.push(1) })\neffect(() => { list.push(2) })\nconsole.log(list.length)"],
    ["同一个同步任务中，count.value 加 1 三次。组件渲染几次？", ["1 次","3 次","0 次","2 次"], "组件的更新任务带有 QUEUED 标记。已经在队列中的任务不再加入。所以三次修改只排了一个任务，在微任务中渲染一次。选 3 次是以为每次修改都同步渲染。数据改变了，所以不是 0 次。", "scheduler"],
    ["组件模板显示 count。日志的顺序是什么？", ["sync watch updated tick","watch sync updated tick","sync updated watch tick","sync tick watch updated"], "同步代码先运行，所以 sync 第一。然后队列运行。flush 为 pre 的侦听器在组件更新前运行。onUpdated 在组件更新后运行。nextTick 的回调最后运行：它在 count.value++ 之后调用，所以排在本次更新之后。watch 不会在 sync 之前运行，因为它进入了队列。", "scheduler",
      "watch(count, () => log('watch'))   // flush: 'pre'\nonUpdated(() => log('updated'))\n\ncount.value++\nlog('sync')\nnextTick(() => log('tick'))"],
    ["修改数据后，要立即读取更新后的 DOM。应该怎样做？", ["await nextTick() 之后读取","直接读取，DOM 已同步更新","在默认的 watch 回调中读取","调用 $forceUpdate() 后读取"], "先修改数据，再 await nextTick()：它返回的 Promise 在这次更新完成后才完成。DOM 在微任务中更新，所以直接读取得到旧内容。watch 默认 flush 为 pre，在组件更新前运行，读到的也是旧 DOM。$forceUpdate 只是把更新加入队列，DOM 仍然没有立即改变。", "scheduler"],
    ["组件显示 count，el 是显示它的元素。下面的代码在事件处理函数里运行，两行日志是什么？", ["pre watch 0、after microtask 1","pre watch 1、after microtask 1","pre watch 0、after microtask 0","after microtask 0、pre watch 1"], "count.value++ 的那一刻，调度器已经把 flushJobs 排进微任务队列。随后 await Promise.resolve() 的后续代码排在它后面，所以后续代码运行时刷新已经完成，DOM 是新的：after microtask 1。pre 侦听器在刷新里、组件渲染之前运行，DOM 还是旧的：pre watch 0。选 after microtask 0 的人以为只有 nextTick 才能等到更新。顺序必须是 pre watch 在前，因为后续代码要等刷新结束才继续。", "scheduler",
      "watch(count, () => log('pre watch ' + el.textContent))\ncount.value++\nawait Promise.resolve()\nlog('after microtask ' + el.textContent)"],
    ["组件显示 items 和 total。下面的代码运行后，这个组件的渲染函数总共运行几次(不含首次挂载)？", ["2 次","1 次","无限次，报 Maximum recursive updates exceeded","0 次"], "push 触发第一次渲染。渲染完成后 onUpdated 把 total 改成 6，total 变了，再触发第二次渲染。第二次渲染后 onUpdated 又把 total 设为 6，值没变，不触发更新，循环结束。所以是 2 次。在 onUpdated 里修改渲染用的数据不一定无限循环，只有每一轮都产生新的变化才会。选“无限次”的人把“可能循环”当成了“一定循环”。", "scheduler",
      "const items = ref([1, 2])\nconst total = ref(3)\nonUpdated(() => {\n  total.value = items.value.reduce((a, b) => a + b, 0)\n})\n// 模板显示 items 和 total\nitems.value.push(3)\nawait nextTick()"],
    ["Parent 的模板是 <Child :n=\"n\" />。点击按钮执行 n.value++，日志的顺序是什么？", ["P watch、P render、C watch、C render","P watch、C watch、P render、C render","P render、P watch、C render、C watch","P watch、P render、C render、C watch"], "Parent 自己的 pre 侦听器在队列里按 id 先运行，再渲染 Parent。Parent 渲染时发现 Child 的 props 变了，先更新 Child 的 props，再调用 flushPreFlushCbs 取出 Child 的 pre 侦听器运行，最后才渲染 Child。所以 pre 侦听器总是在它所属组件渲染之前运行，但不一定在所有组件渲染之前。选第二项的人以为所有 pre 侦听器都先于所有渲染。第四项把 Child 的 pre 侦听器当成了渲染之后的回调。", "scheduler",
      "// Parent: watch(n, () => log('P watch'))，渲染时 log('P render')\n// Child:  watch(() => props.n, () => log('C watch'))，渲染时 log('C render')\nn.value++"],
    ["子组件 Child 自己的数据 c 先改，同一段同步代码里，父组件又把 v-if 的条件改成 false 卸载了 Child。刷新结束后，两个渲染函数各运行几次？", ["Parent 1 次，Child 0 次","Parent 1 次，Child 1 次","Parent 0 次，Child 1 次","Parent 1 次，Child 2 次"], "更新队列按 id 排序，父组件的更新任务先运行。Parent 渲染时发现 Child 不再需要，卸载它，并给 Child 的更新任务打上已销毁（disposed）标记。轮到 Child 的任务时被直接跳过，所以 Child 的渲染函数一次都没有运行。选 Child 1 次的人以为数据变了就一定渲染。选 Parent 0 次的人忘了 show 的修改也让 Parent 入队。", "scheduler",
      "// Child 的渲染函数读取 c；Parent 的渲染函数读取 show：show ? h(Child) : null\nc.value++\nshow.value = false"],
    ["count 显示在组件里。下面的代码在事件处理函数中运行，三行日志是什么？", ["sync 0、tick 0","sync 0、tick 1","sync 1、tick 1","sync 1、tick 0"], "nextTick 调用时还没有安排刷新，返回的是已经完成的 Promise，它的回调先进入微任务队列。count.value++ 随后才安排刷新，刷新的微任务排在回调后面。所以 tick 回调读到旧 DOM：0，同步的那行也是 0。页面最后仍会更新为 1，但这两个回调都在更新之前运行。选 tick 1 的人以为 nextTick 总是等刷新，其实它等的是“调用时已经安排的刷新”。", "scheduler",
      "nextTick(() => log('tick ' + el.textContent))\ncount.value++\nlog('sync ' + el.textContent)"],
    ["Parent 的渲染函数读取 pd 并渲染 Child，Child 的渲染函数读取 cd，两个组件都有 onUpdated。下面的代码同步运行后，日志的顺序是什么？", ["P render、C render、P updated、C updated","C render、P render、C updated、P updated","P render、C render、C updated、P updated","C render、C updated、P render、P updated"], "两个组件的更新任务按 id 排序，Parent 的 id 小，先渲染，Child 随后渲染，与修改的先后无关。onUpdated 是后置任务：Parent 先 patch 完，它的 onUpdated 先进入后置队列。Child 在 Parent 之后才 patch 完（Parent 的 props 没有变，Child 没有在 Parent 的 patch 里更新），所以 P updated 在 C updated 之前。选第三项的人套用了“子先于父”的规则，那只适用于子组件在父组件的 patch 里同步更新的情形。", "scheduler",
      "cd.value++   // 先改子组件的数据\npd.value++   // 再改父组件的数据（Parent 没有给 Child 传 props）"],
    ["`h(Comp, null, { default: () => h('b') })` 和 `h(Comp, null, [h('b')])` 对子组件的区别是什么？", ["前者的插槽函数由子组件的渲染调用，依赖归子组件；后者的数组在父组件渲染时已创建，依赖归父组件，开发环境还会警告","没有区别，两种写法都会被规范化成同一个插槽对象","前者会报错，插槽必须是数组","后者更快，因为数组不需要调用函数"], "插槽对象里的值应该是函数：子组件调用它时才创建内容，读到的响应式数据被子组件的渲染副作用函数收集。数组在父组件渲染时就创建完了，数据归父组件，还不能接收子组件传来的参数。Vue 开发环境对数组形式发出 Non-function value encountered for default slot 警告，内容仍会显示。", "render"],
    ["SepList 的渲染函数对 `slots.default()` 返回的数组逐项插入 `h('hr')`。使用者写 `<SepList><p>a</p><p>b</p></SepList>`，渲染出的 hr 有几条？", ["1 条，在 a 和 b 之间","0 条","2 条","3 条"], "两个静态的 p 是两个并列的 vnode，数组有两项，逐项插入会在第二项前加一条 hr。如果使用者用的是 v-for，数组只有一项（一个 Fragment），就一条也不会插入。选 2 条的人把分隔线加在了每一项后面，而代码是从第二项开始加。", "render",
      "setup(_, { slots }) {\n  return () => {\n    const items = slots.default?.() ?? []\n    return h('div', items.flatMap((vn, i) => (i === 0 ? [vn] : [h('hr'), vn])))\n  }\n}"],
    ["`h('div', null, 'a', 'b')` 的 `shapeFlag` 和 `children` 分别是什么？", ["17，children 是数组 ['a', 'b']","9，children 是字符串 'ab'","1，children 是 null","8，children 是 'a'"], "三个以上的参数时，第三个起都是子节点，收成数组，所以是元素位 1 加数组子节点位 16，等于 17。选 9 的人以为多个文字会拼成一段文字。选 1 的人以为多余的参数被忽略。", "render"],
    ["编译结果中 patchFlag 为 1 表示什么？", ["只有文字内容是动态的","class 是动态的","整个节点是静态的","需要比较全部属性"], "PatchFlags.TEXT 等于 1。更新时，Vue 只比较文字，跳过属性。class 动态是 2。完全静态的节点是 -1：Vue 3.5 已把它缓存，更新时跳过，所以第三项错。需要比较全部属性的是 FULL_PROPS，值为 16。", "compiler"],
    ["Block 节点的 dynamicChildren 保存什么？", ["动态后代和子 Block 的根","全部子节点，包括静态节点","只有直接子节点中的动态节点","子 Block 内部的全部动态节点"], "动态后代指带 patchFlag 的元素和组件。Block 收集所有层级的动态后代，跳过中间的静态层级。v-if 和 v-for 会创建子 Block。子 Block 内部的节点保存在它自己的 dynamicChildren 中。所以不包括静态节点，也不只是直接子节点。子 Block 的内部不平铺到外层。", "compiler"],
    ["下面是一段编译结果。它对应哪个模板？", ["<p :id=\"a\" :class=\"c\">{{ m }}</p>","<p :id=\"a\" :class=\"c\" :title=\"t\">{{ m }}</p>","<p :id=\"a\" :class=\"c\">固定文字</p>","<p v-bind=\"{ id: a, class: c }\">{{ m }}</p>"], "11 = 1 + 2 + 8：TEXT、CLASS、PROPS。TEXT 说明有插值，CLASS 说明 class 是动态的，PROPS 加 dynamicProps [\"id\"] 说明除 class 以外只有 id 是动态的。多一个 :title 时 dynamicProps 是 [\"id\", \"title\"]。文字固定时没有 TEXT，标记是 10。v-bind 对象的键名不确定，标记含 FULL_PROPS（16），也没有 dynamicProps；加上 TEXT 是 17。", "compiler",
      "_createElementBlock(\"p\", {\n  id: _ctx.a,\n  class: _normalizeClass(_ctx.c)\n}, _toDisplayString(_ctx.m), 11 /* TEXT, CLASS, PROPS */, [\"id\"])"],
    ["下面的代码用 compile 编译一个模板，并传入自己的节点转换。输出什么？", ["p undefined","p 3","p 3 /* TEXT, CLASS */","什么也不输出：退出函数不会被调用"], "compile 把 nodeTransforms 选项里的函数追加在内置转换之后。退出函数按相反的顺序运行，所以 spy 的退出函数比 transformElement 的退出函数先运行。这时 codegenNode 还没有生成，codegenNode?.patchFlag 是 undefined。退出函数会被调用，所以不是“什么也不输出”。要读到 3，需要自己调用 transform，把转换放在数组最前面，让它最后退出。", "compiler",
      "const spy = node => {\n  if (node.type !== NodeTypes.ELEMENT) return\n  return () => console.log(node.tag, node.codegenNode?.patchFlag)\n}\ncompile('<p :class=\"c\">{{ m }}</p>', { nodeTransforms: [spy] })"],
    ["这个组件用生产构建（内联模板）编译。渲染函数里，三个变量怎样读取？", ["count.value、label、_unref(n)","$setup.count、$setup.label、$setup.n","count.value、label、n","_ctx.count、_ctx.label、_ctx.n"], "compileScript 知道 count 是 const 声明的 ref，所以直接写 count.value。label 是字面量常量，直接引用。n 用 let 声明，之后可能被赋值成 ref，所以用 _unref(n) 读取。$setup.xxx 是开发模式（模板单独编译）的读法，_ctx.xxx 是没有 script setup 绑定信息时的读法。", "compiler",
      "<script setup>\nimport { ref } from 'vue'\nconst count = ref(0)\nconst label = 'hi'\nlet n = 1\n</script>\n\n<template><p>{{ count }} {{ label }} {{ n }}</p></template>"],
    ["编译一个带 script setup 的 .vue 文件。要把模板里的 count 编译成 $setup.count，compileTemplate 需要先拿到哪一步的结果？", ["compileScript：它返回的 bindings 记录了每个变量的来源","compileStyle：它生成的 scope id 决定变量的前缀","parse：它扫描 script 里的声明，返回 bindings","不需要：所有变量都编译成 _ctx.xxx，运行时再查找"], "compileScript 分析 script setup，返回 bindings：count 是 setup 里的 ref，Child 是导入的常量。compileTemplate 通过 compilerOptions.bindingMetadata 收到它，才能把变量写成 $setup.count 和 $setup[\"Child\"]。parse 只拆块，不分析变量。compileStyle 只处理样式。没有 bindings 时才会退回 _ctx.xxx。", "compiler"],
    ["下面的模板被编译成渲染函数。根 div 的 dynamicChildren 里有几个节点？", ["1 个：v-if 的 p 是一个子 Block；静态的 span 被缓存，不收集","2 个：p 和 span","0 个：根 div 没有动态绑定","1 个：span，因为 p 的 v-if 在运行时才知道"], "v-if 的分支是一个独立的 Block，它作为一个节点出现在根 Block 的 dynamicChildren 里，分支内部的动态节点在它自己的 dynamicChildren 里。span 是静态节点，被缓存（-1），不收集。第三项忘了结构可能变化的 v-if 要创建 Block。第四项把静态节点当成动态的。用 @vue/compiler-dom 3.5.43 编译实测。", "compiler",
      "<div>\n  <p v-if=\"ok\">{{ a }}</p>\n  <span>static</span>\n</div>"],
    ["用 SFC 编译下面的 button。它的 PatchFlag 和 dynamicProps 是什么？", ["8（PROPS），dynamicProps 是 [\"disabled\"]：onClick 被缓存，不算动态","8（PROPS），dynamicProps 是 [\"onClick\", \"disabled\"]","16（FULL_PROPS）：有事件监听就要比较全部属性","1（TEXT），因为文字 x 是固定的所以没有其他标记"], "SFC 编译默认缓存事件处理函数（_cache[0]），所以 onClick 每次渲染都是同一个函数，不进 dynamicProps。:disabled 是除 class 和 style 以外的动态属性，得到 PROPS（8），dynamicProps 是 [\"disabled\"]。第二项是关闭事件缓存时的结果。FULL_PROPS 只在键名不确定（v-bind=\"obj\"）时出现。文字固定，没有 TEXT。用 @vue/compiler-sfc 3.5.43 实测。", "compiler",
      "<button @click=\"f\" :disabled=\"d\">x</button>"],
    ["下面的模板有三个子元素。编译后，哪些会被放进 _cache 缓存为静态节点（PatchFlag -1）？", ["只有 p：div 带 ref，得到 512（NEED_PATCH），不缓存；span 有动态属性","div 和 p：它们的内容都是固定文字","只有 div：ref 是静态的字符串","三个都缓存：缓存只看有没有响应式数据"], "静态节点要同时满足：没有动态绑定，没有 ref 和运行时指令，所有子节点也静态。div 的内容固定，但写了 ref，运行时要处理它，得到 512（NEED_PATCH），不缓存。p 满足条件，得到 -1 并缓存。span 有 :id，得到 PROPS（8）。用 @vue/compiler-sfc 3.5.43 实测。", "compiler",
      "<div>\n  <div ref=\"el\">s</div>\n  <p>t</p>\n  <span :id=\"i\">u</span>\n</div>"],
    ["Vapor 模式编译 <button @click=\"count++\">{{ count }}</button>。count 变化时，运行时做什么？", ["只重新执行那一个把 count 写进文字节点的渲染副作用函数，不生成 vnode，也不 diff","重新运行整个组件的渲染函数，生成新 vnode，再用 PatchFlag 跳过静态部分","重新克隆整个 template，替换掉旧的 DOM","把 count 加入 dynamicChildren，由 Block 比较"], "Vapor 把模板编译成直接操作 DOM 的代码：静态结构用 template 克隆一次，每个动态绑定是一个小的渲染副作用函数（_renderEffect），订阅它读到的数据。count 变了，只有写文字的那个副作用函数重新执行。没有 vnode，没有 diff，也不需要 PatchFlag 和 Block。第二项是本章主线讲的虚拟 DOM 模式。第三项和第四项都不是 Vapor 的做法。Vapor 属于 Vue 3.6（核实日期 2026-10-09 时仍是候选发布阶段）。", "compiler"],
    ["没有写 key 的列表从 `a b` 变成 `x a b`，每项是一个 li，文字是数据。渲染器对页面做了什么？", ["更新第 1、2 个 li 的内容，再新挂载第 3 个 li","只在最前面新挂载一个 li","卸载两个 li，再挂载三个 li","把两个 li 向后移动一位，再挂载一个"], "没有 key 时按下标一一对应：第 0 个 li 的文字从 a 改成 x，第 1 个从 b 改成 a，多出的第 2 个新挂载。节点从不移动，也不卸载。选只挂载一个的人以为 Vue 会认出 a、b 没变，那需要 key。", "diff"],
    ["旧列表 `a b c d e f g`，新列表 `g a b c d e f`，都有 key。Vue 移动几个已有节点？", ["1 个，只移动 g","6 个，a 到 f 各移动一次","7 个，全部移动","0 个，新节点只需挂载"], "头尾同步都对不上（a 对 g，g 对 f）。newIndexToOldIndex 是 [7, 1, 2, 3, 4, 5, 6]，最长递增子序列是 1 到 6，长度 6。这 6 个节点不动，只有 g 移到最前面。选 6 个的人把“不动的”和“移动的”弄反了。", "diff",
      "// 新列表中每个节点对应的旧下标加 1\n[7, 1, 2, 3, 4, 5, 6]"],
    ["两个都有 key 的 li 数组：旧 `a b c`，新 `a b c d`。`patchKeyedChildren` 的第 3 步把 d 挂载到哪个锚点前面？", ["没有锚点：parentAnchor，也就是追加到末尾","c 的前面","a 的前面","先挂到末尾，再移动到 c 后面"], "头部同步处理完 a、b、c，旧的比完了。锚点是 c2[e2 + 1] 的真实节点，这里 e2 + 1 等于新数组长度，没有后继，所以用父级传下来的 parentAnchor（这里是 null），追加到末尾。挂载一次完成，不需要再移动。", "diff"],
    ["Tabs 和 Tab 是一组复合组件。Tab 怎样找到它所属的 Tabs？", ["Tabs 用 provide，Tab 用 inject","Tabs 用 props 把自己传给 Tab","Tab 读取 $parent 找到 Tabs","Tab 用 emit 向 Tabs 注册自己"], "provide/inject 不依赖组件的层级，Tab 外面再包一层组件也能工作。props 需要使用者手动传递，容易漏掉。$parent 在中间多一层组件时就指错了。emit 只能通知直接父组件，而且父组件要写监听。", "patterns"],
    ["TreeItem.vue 要显示多层的树。哪种写法正确？", ["模板中直接写 <TreeItem>","必须改用 h() 渲染函数才能递归","要先在父组件中注册它才能递归","用 v-html 拼接子树的 HTML"], "SFC 可以用文件名引用自己，不需要注册。模板中写 <TreeItem v-for=\"c in node.children\" :node=\"c\" />。children 为空时，v-for 不渲染，递归就停止。模板可以递归，所以不必改用渲染函数。v-html 拼接字符串会失去组件和事件，还有 XSS 风险。", "patterns"],
    ["页面组件因为 count 变化重新渲染。传给 UserCard 的 user 对象没有变。UserCard 的渲染函数会再运行吗？", ["不会：Vue 浅比较子组件的 props，没有变化就跳过这个子组件","会：父组件重新渲染时，它的所有子组件都跟着重新渲染","会：count 是父组件的状态，子组件也依赖它","不会：展示组件不使用响应式数据，Vue 不会更新它"], "父组件的渲染函数每次运行，都会重新创建子组件的 vnode。patch 到子组件时，Vue 逐个用 !== 比较 props。user 是同一个对象，没有变化，子组件的更新被跳过。所以第二项错：不是所有子组件都跟着渲染。第三项错：子组件没有读 count，不依赖它。第四项错：UserCard 里的 props 和响应式数据照常工作，跳过更新的原因是 props 没变，与展示组件无关。注意：父组件每次渲染都传一个新的对象字面量（例如 :user=\"{ ...user }\"）时，props 会算作变化，子组件照样更新。", "patterns",
      "<!-- 父组件：count 每点一次加 1 -->\n<button @click=\"count++\">{{ count }}</button>\n<UserCard :user=\"user\" />"],
    ["UserForm 用 watch 在父组件换数据时重置草稿。父组件这样使用它。用户在输入框里敲了几个字，这时点击按钮，count 加 1，父组件重新渲染。输入框里的字会怎样？", ["被冲掉，输入框回到 user 的值：每次渲染都是一个新对象，watch 被触发","保留：user 里的内容没有变，watch 不会触发","保留：watch 只在 immediate 时才运行","报错：不能在模板里展开对象"], "watch(() => props.user, …) 比较的是 props.user 的引用。模板里的 { ...user } 在父组件每次渲染时都创建一个新对象，引用每次都不同，watch 触发，Object.assign 把草稿重置成 user 的当前值，用户没保存的输入被冲掉。第二项以为 watch 比较内容，它比较的是引用。第三项把 immediate 和触发条件弄混了：immediate 只决定创建时是否运行一次。展开对象是合法的模板表达式。修法：传稳定的对象（直接传 user），或者只侦听 props.user.id。", "patterns",
      "// UserForm.vue\nconst draft = reactive({ ...props.user })\nwatch(() => props.user, u => Object.assign(draft, u))\n\n<!-- 父组件 -->\n<button @click=\"count++\">{{ count }}</button>\n<UserForm :user=\"{ ...user }\" />"],
    ["Pinia setup store 中，ref、computed 和函数分别对应什么？", ["state、getter、action","getter、state、action","action、getter、state","state、state、action"], "ref 是 state，computed 是 getter，函数是 action。这和组件的 setup 写法相同。computed 是派生数据，所以不是 state。在组件中解构 state 和 getter 时，使用 storeToRefs。", "pinia"],
    ["下面的 cart store 在创建时读取了 auth。用户之后登录，canCheckout 会怎样？", ["一直是 false，loggedIn 只是创建时的一个值","登录后变为 true，store 会自动跟踪","报错，store 里不能使用另一个 store","刷新页面后才变为 true"], "`useAuthStore().loggedIn` 在 setup 里读出的是当时的 false，存进普通变量后不再变化，computed 里读的是这个变量，没有依赖任何响应式数据。要在 computed 里读 `auth.loggedIn`（auth 是 store 对象），这样才会跟踪。store 里可以使用另一个 store，所以第三项不对。", "pinia",
      "const useCart = defineStore('cart', () => {\n  const loggedIn = useAuthStore().loggedIn\n  const items = ref([])\n  const canCheckout = computed(() => loggedIn && items.value.length > 0)\n  return { items, canCheckout }\n})"],
    ["board 的 state 是 `{ tags: ['a', 'b'], filter: { owner: 'ann', status: 'todo' } }`。执行 `board.$patch({ tags: ['c'], filter: { status: 'done' } })` 后，state 是什么？", ["tags 是 ['c']，filter 是 { owner: 'ann', status: 'done' }","tags 是 ['a', 'b', 'c']，filter 是 { status: 'done' }","tags 是 ['c']，filter 是 { status: 'done' }","tags 是 ['a', 'b', 'c']，filter 是 { owner: 'ann', status: 'done' }"], "$patch 的对象形式把嵌套的普通对象逐层合并（filter 保留 owner），数组则整个替换（tags 变成 ['c']）。要向数组追加一项，用函数形式 `$patch(s => s.tags.push('c'))`。", "pinia"],
    ["组件 A 的 setup 里调用 `store.$subscribe(save)` 保存数据。A 被 v-if 销毁后，用户继续修改 store，会怎样？", ["不再保存，订阅随组件卸载取消","继续保存，订阅属于 store","报错，订阅了已卸载组件的 store","只保存最后一次修改"], "在组件里调用 $subscribe，订阅默认绑定在这个组件上，组件卸载时自动取消。要让订阅一直有效，传 `{ detached: true }`，或者把订阅写在不会卸载的地方（插件、应用入口）。", "pinia"],
    ["从 /user/1 跳到 /user/2。路由配置里的 beforeEnter 会运行吗？", ["不运行，路由没变，只是参数变了","运行，每次导航都会运行","运行，因为参数变了","只在第一次访问 /user/1 时运行，之后永远不运行"], "beforeEnter 只在“进入”这条路由时运行。两个地址匹配同一条路由记录，组件被复用，运行的是组件内的 beforeRouteUpdate，全局守卫（beforeEach 等）仍然运行。离开 /user 再回来，beforeEnter 会再次运行，所以最后一项不对。", "router"],
    ["路由 `{ path: '/start', component: Home, alias: '/home' }` 和 `{ path: '/old', redirect: '/start' }`。访问 /home 和 /old 后，地址栏分别是什么？", ["/home 和 /start","/start 和 /start","/home 和 /old","/start 和 /old"], "alias 让另一个路径显示同一个组件，地址栏保持用户输入的 /home。redirect 把导航改成去另一个地址，地址栏变成 /start。", "router"],
    ["守卫对 /admin 返回了 '/login'（重定向）。`const r = await router.push('/admin')` 之后，r 和当前路由是什么？", ["r 是 undefined，当前路由是 /login","r 是 NavigationFailure（aborted），当前路由不变","r 是 NavigationFailure（redirected），当前路由是 /login","push 抛出异常"], "守卫返回新地址是重定向，不算失败：push 正常完成，resolve undefined，最终到达 /login。只有返回 false（aborted）、导航被新导航取代（cancelled）、目标和当前相同（duplicated）才是 NavigationFailure。", "router",
      "router.beforeEach(to => {\n  if (to.path === '/admin') return '/login'\n})\nconst r = await router.push('/admin')"],
    ["用户在受保护的 /dashboard 刷新页面，被送到了登录页，但他的 token 还保存着。下面的守卫缺了什么？", ["等 auth.restore() 完成再判断登录状态","对 /login 也做重定向","把 token 写进 URL","改用 beforeEnter"], "刷新后内存里的 user 没了，守卫运行时 loggedIn 是 false，把登录着的用户踢走。守卫是 async 函数，Router 会等它，所以先 `await auth.restore()`（用 token 换回用户）再判断。对 /login 重定向会无限循环。", "router",
      "router.beforeEach((to) => {\n  const auth = useAuthStore()\n  if (to.meta.requiresAuth && !auth.loggedIn) {\n    return { path: '/login', query: { redirect: to.fullPath } }\n  }\n})"],
    ["Vue 3.5 中，要给可选的 items 默认值 []。哪种写法正确？", ["const { items = [] } = defineProps<P>()","defineProps<P>({ items: { default: [] } })","defineProps<{ items?: string[] = [] }>()","const p = defineProps<P>(); p.items ??= []"], "Vue 3.5 支持解构 defineProps 并写默认值。编译器把默认值移到 props 选项中，解构的变量仍是响应式的。defineProps 不能同时接收类型参数和运行时参数，编译器报错。TypeScript 的类型中不能写默认值。props 是只读的，??= 赋值无效，开发环境显示警告。3.5 之前写 withDefaults(defineProps<P>(), { items: () => [] })。", "ts",
      "type P = { items?: string[] }"],
    ["下面的组件用 vue-tsc 检查，报 TS2769: No overload matches this call，位置在 watch 那一行。最合适的改法是什么？", ["把 watch 的第一个参数改成 getter：watch(() => status, …)","给 status 加类型断言：watch(status as any, …)","把 defineProps 的解构改回 const props = defineProps(…)，因为解构的 prop 不能被 watch","import { toRef } 之后写 watch(toRef(status), …)"], "Vue 3.5 的解构 prop 在编译后是 __props.status，在源码里看起来是一个普通的字符串，不是 ref，所以 watch 的重载匹配不上。要监听它，用 getter 包一层：watch(() => status, …)，getter 里读取 __props.status，依赖会被跟踪。第二项用 as any 只是让编译器闭嘴，运行时 watch 一个字符串仍然不监听任何东西。第三项说法过强：解构的 prop 完全可以被监听，只是要用 getter。第四项：toRef(status) 传入的是一个字符串，不是 reactive 对象的属性，同样无效。", "ts",
      "<script setup lang=\"ts\">\nimport { watch } from 'vue'\nconst { status = 'todo' } = defineProps<{ status?: string }>()\nwatch(status, (v) => console.log(v))   // error TS2769: No overload matches this call.\n</script>"],
    ["useTitle 的参数类型是 MaybeRefOrGetter<string>。n 是 Ref<number>，s 是 Ref<string>。下面四个调用，vue-tsc 会对哪两个报错？", ["useTitle(n) 和 useTitle(() => n.value)","useTitle(s) 和 useTitle(() => `n=${n.value}`)","只有 useTitle(n)，因为 getter 函数总是被允许","useTitle(n) 和 useTitle(s)，因为 ref 都不被允许"], "MaybeRefOrGetter<string> 等于 string | Ref<string> | (() => string)。useTitle(n)：Ref<number> 不是 Ref<string>，报 TS2345。useTitle(() => n.value)：getter 返回 number，不是 string，同样报 TS2345（实测两条都是 TS2345）。useTitle(s) 和模板字符串的 getter 都符合。第三项错在 getter 的返回类型也要匹配。第四项错在 ref 本身是允许的，只要里面的类型对。", "ts",
      "function useTitle(title: MaybeRefOrGetter<string>) { … }\nconst n = ref(1)\nconst s = ref('a')\nuseTitle(s)\nuseTitle(n)\nuseTitle(() => n.value)\nuseTitle(() => `n=${n.value}`)"],
    ["有人在 src/types/vue-augment.d.ts 里只写了下面的代码。保存后，整个项目里每一处 import { ref } from 'vue' 都报 TS2305: Module '\"vue\"' has no exported member 'ref'。原因是什么？", ["文件没有顶层 import 或 export，declare module 'vue' 变成了替换整个 vue 类型的声明，而不是扩充","ComponentCustomProperties 不能被扩充，Vue 因此拒绝所有导出",".d.ts 文件不能放在 src 目录下，要放在项目根目录","$t 的类型写错了，函数类型必须写成 interface"], ".d.ts 文件里没有顶层的 import 或 export 时，它是全局脚本，declare module 'vue' 声明了一个新的模块，原来的 vue 类型就不再生效，所以 ref 等导出全部消失。只要加一行 export {}（或写任何一个 import），它就成为模块文件，declare module 变成扩充，与原有类型合并。扩充 ComponentCustomProperties 是官方支持的做法。文件放在 src/ 下正好被 tsconfig.app.json 的 include 覆盖。", "ts",
      "declare module 'vue' {\n  interface ComponentCustomProperties {\n    $t: (key: string) => string\n  }\n}"],
    ['渲染 10000 行数据时，页面卡顿。通常最有效的方法是什么？', ['虚拟列表，只渲染可见的行', '把 ref 换成 reactive', '用 v-show 代替 v-if', '给每一行加上 v-once'], '虚拟列表让 DOM 数量只和可见区域的大小有关，和数据量无关。reactive 和 ref 的速度差别很小，不是瓶颈。v-show 仍然创建全部元素。v-once 只跳过以后的更新，第一次仍然创建 10000 行。', 'perf'],
    ['父组件写 <Child :opts="{ size: 1 }" />。父组件因为其他数据重新渲染时，Child 怎样？', ['也更新，因为对象是新的', '跳过，因为内容相同', '只在第一次渲染时更新', '报错，不能传对象字面量'], '每次渲染都创建一个新对象。Vue 用 === 比较 props。新对象和旧对象不相等，所以 Child 更新。Vue 不比较对象的内容。传对象字面量是合法的。修复：在 setup 中声明这个对象，或传原始值。', 'perf'],
    ["`npm create vue@latest` 建的 TypeScript 项目里，`src/stores/counter.ts` 末尾有一行 `export const bad: number = 'x'`。运行下面两条命令，结果是什么？", ["`vue-tsc --noEmit` 退出码 0、没有输出；`vue-tsc --build` 报 `TS2322` 并退出码非 0","两条命令都报 `TS2322`","两条命令都通过，因为 Vite 构建不检查类型","`vue-tsc --noEmit` 报错，`vue-tsc --build` 通过"], "脚手架的根 `tsconfig.json` 是 `\"files\": []` 加 `references`。`--noEmit` 不跟随引用，等于没有文件可检查，静默通过。`--build` 按引用逐个检查，报出错误（实测退出码 2）。所以脚手架项目的 CI 要用 `npm run type-check`。", "tooling"],
    ["项目有 `.env`（`VITE_API_BASE=https://api.example.com`）和 `.env.staging`（`VITE_API_BASE=https://staging.example.com`）。运行 `vite build --mode staging`，打包文件里 `import.meta.env.VITE_API_BASE` 被替换成什么？", ["`https://staging.example.com`：`.env.staging` 覆盖 `.env` 里的同名变量","`https://api.example.com`：`.env` 优先","构建报错：两个文件有同名变量","两个值都保留，运行时再选"], "指定模式后，Vite 加载 `.env` 和 `.env.[mode]`，同名变量以模式文件为准。构建时直接替换成字符串，打包文件里没有“运行时再选”的机制（实测 `import.meta.env.MODE` 是 `staging`，`PROD` 仍为 true）。", "tooling"],
    ["部署后，新版本发布了，但部分用户的页面一直是旧版本。服务器给所有文件，包括 `index.html`，都设了 `Cache-Control: max-age=31536000`。应该怎样改？", ["`assets/` 里带哈希的文件继续长期缓存，`index.html` 改成 `no-cache`","去掉所有文件的缓存","给 `index.html` 也加哈希文件名","把 `assets/` 的缓存也缩短到一小时"], "带哈希的文件内容变了文件名就变，可以长期缓存。`index.html` 的名字固定，却引用着这些带哈希的文件：它被长期缓存，用户就一直拿到引用旧文件的页面。给它 `no-cache`，每次向服务器确认。入口 HTML 的文件名要固定，所以不能加哈希。", "tooling"],
    ["SSR 水合时，元素类型和虚拟节点不同。Vue 做什么？", ["删除这个节点，创建新节点","保留服务器的节点，只显示警告","重新渲染整个应用的 DOM","停止水合，页面不能交互"], "元素类型不同时，Vue 不能复用这个节点，所以删除它并创建新节点。只修改这一个节点，不重新渲染整个应用，水合也继续进行。保留服务器的值只发生在 class 和 style 不匹配时；用 v-bind 绑定的其他动态属性（例如 :title）会被改成客户端的值。文字不同时，Vue 修改文字。", "ssr"],
    ["服务器渲染时得到了两个用户。客户端水合时，setup 重新运行，users 是空数组。水合后，列表显示什么？", ["空列表，Vue 按客户端数据修正","Ann 和 Bob，保留服务器的节点","Ann 和 Bob，数据自动传过来","页面报错，水合在列表处中断"], "水合时，Vue 用客户端的虚拟节点检查服务器的 DOM。客户端列表为空，所以 Vue 删除多出的两个 li，并报告不匹配。服务器的数据不会自动传给客户端。正确做法：服务器把状态写入 HTML（例如 Pinia 的 state）。客户端先用它初始化 users。子节点不同时，水合继续进行，页面可以交互。", "ssr",
      "// 服务器 HTML：<ul><!--[--><li>Ann</li><li>Bob</li><!--]--></ul>\nconst users = ref([])   // 客户端 setup 中，请求还没有完成\n// 模板：<li v-for=\"u in users\" :key=\"u\">{{ u }}</li>"],
    ["服务器用 renderToNodeStream 渲染下面的组件。根组件的 setup 是 async，里面 await 了 300 毫秒的请求，模板里没有别的异步组件。浏览器大约什么时候收到第一块 HTML？", ["约 300 毫秒，根组件的 setup 完成之后","几乎立刻，先发静态的 header","几乎立刻发出 div 的开始标签，其余等 300 毫秒","不会发出，async 的根组件不支持流式渲染"], "流要先拿到根组件的 buffer 才能开始展开。根组件的 async setup 没完成，就没有 buffer，所以第一个字节也要等。如果把请求放到下层组件里，根组件的静态部分就可以先发出。静态内容不能越过根组件的 Promise。流式渲染支持 async 的根组件，只是它挡住一切。", "ssr",
      "// 根组件\nasync setup() {\n  await fetchArticle()   // 300 毫秒\n}\n// 模板：<div><header>top</header><Body /></div>"],
    ["服务器 HTML 是 <p class=\"a\" title=\"x\">hi</p>。客户端模板和数据如下。水合完成后，这个 p 是什么样？", ["class=\"a\" title=\"y\"，文字是 yo","class=\"b\" title=\"y\"，文字是 yo","class=\"a\" title=\"x\"，文字是 hi","class=\"a\" title=\"x\"，文字是 yo"], "文字不同时 Vue 改成客户端的值（yo）。title 用 v-bind 绑定，进了 dynamicProps，水合时调用 patchProp，改成 y。class 不会被修正，保留服务器的 a。第二项以为 class 也会被改。第四项以为所有属性都不改，只改文字。", "ssr",
      "// 客户端\nconst c = ref('b'), t = ref('y'), m = ref('yo')\n// 模板：<p :class=\"c\" :title=\"t\">{{ m }}</p>"],
    ["页面用 hydrate: hydrateOnVisible() 延迟水合 Chart。页面加载完成时，Chart 在首屏下方，用户还没有滚动。此时 Chart.vue 的 JavaScript 文件和 setup 的状态是什么？", ["文件已经请求，setup 还没有运行，滚动到可见才运行","文件还没有请求，滚动到可见才请求并运行","文件已经请求，setup 已经运行，只是没有绑定事件","文件和 setup 都已就绪，滚动到可见才绑定事件"], "延迟水合推迟的是水合：运行 setup、render 并接管 DOM。水合流程走到这个组件时就调用了 loader，所以 import() 的文件已经请求。只有进入视口，策略才调用真正的水合函数。第二项是最常见的误解：以为延迟水合同时延迟下载。第三项和第四项把 setup 和事件绑定拆开了，它们都属于水合。", "ssr",
      "const Chart = defineAsyncComponent({\n  loader: () => import('./Chart.vue'),\n  hydrate: hydrateOnVisible()\n})"],
    ["createRenderer 需要你提供什么？", ["创建、插入、删除节点和设置属性的函数","一个新的模板编译器和指令系统","新的响应式系统和更新调度器","一个新的 diff 算法和组件实例"], "你提供 nodeOps（createElement、insert、remove 等）和 patchProp。runtime-core 只通过这些函数操作节点。编译器、响应式、调度器、diff 和组件都可以直接复用。", "renderer"],
    ["自定义渲染器中，带 key 的列表从 a b c 变为 a c。nodeOps 中被调用的是什么？", ["只调用一次 remove，删除 b","remove(b)，再 insert(c)","patchProp，把 b 改为 c","全部删除，再 createElement"], "diff 先同步头部的 a，再同步尾部的 c。中间只剩旧的 b，所以只调用 remove(b)。c 的相对位置没有变，不需要 insert。key 不同的节点不能通过 patchProp 互相修改。Vue 不删除全部再重建，这正是 diff 要避免的。", "renderer"],
    ["自定义渲染器的 patchProp 写成 el.props[key] = next。组件第一次渲染 h('div', { title: 'a' })，第二次渲染 h('div', null)。第二次渲染后，div.props 是什么？", ["{ title: null }","{}","{ title: undefined }","{ title: 'a' }"], "属性被删除时，Vue 调用 patchProp(el, 'title', 'a', null)，next 是 null。这个 patchProp 只是把 null 存了进去，所以键还在，值是 null。要真正删除，需要在 next 为 null 时 delete el.props[key]。第四项以为没有新的 props 就不会调用 patchProp，但 Vue 会比较新旧 props，发现 title 不见了。", "renderer",
      "patchProp(el, key, prev, next) {\n  el.props[key] = next\n}"],
    ["同一个按钮，三次渲染分别是 h('button', { onClick: a })、h('button', { onClick: b })、h('button', {})，用 runtime-dom 的 createApp 渲染。addEventListener 和 removeEventListener 各被调用几次？", ["add 1 次，remove 1 次","add 2 次，remove 2 次","add 2 次，remove 1 次","add 1 次，remove 0 次"], "第一次渲染创建 invoker 并 addEventListener。第二次换了处理函数，只改 invoker.value，不重新绑定。第三次 onClick 没有了，才 removeEventListener 并清掉 invoker。所以是 add 1 次、remove 1 次。第二项和第三项把“换处理函数”当成了先解绑再绑定。第四项忘了 onClick 消失时要解绑。", "renderer",
      "// 渲染 1\nh('button', { onClick: a })\n// 渲染 2\nh('button', { onClick: b })\n// 渲染 3\nh('button', {})"],
    ["页面里有 <div id=\"app\" v-cloak>{{ msg }}</div>。使用带编译器的 Vue 构建，根组件只有 data。执行下面的代码后，#app 是什么样？", ["<div id=\"app\" data-v-app=\"\">hi</div>","<div id=\"app\" v-cloak data-v-app=\"\">hi</div>","<div id=\"app\" v-cloak>{{ msg }}</div>，Vue 报错没有模板","<div id=\"app\" data-v-app=\"\"></div>，容器被清空"], "runtime-dom 的 app.mount 在根组件没有 render 和 template 时，把容器的 innerHTML 当模板，所以 {{ msg }} 被渲染成 hi。挂载前清空容器，挂载后移除 v-cloak 并添加 data-v-app。第四项只对了一半：容器确实会被清空，但模板已经先从 innerHTML 取走了。", "renderer",
      "createApp({ data: () => ({ msg: 'hi' }) }).mount('#app')"],
    ["自定义渲染器（节点是普通对象，没有 classList）里渲染下面的组件。首次挂载时 show 是 true，之后改成 false。哪一项正确？", ["首次挂载成功；show 变为 false 触发离开时抛 TypeError","首次挂载时就抛 TypeError","全程正常：Transition 把 remove 推迟到动画结束","全程正常：自定义渲染器自动跳过过渡"], "Transition 属于 runtime-dom。没有 appear 时，首次挂载不会调用进入钩子，所以挂载本身不出错。show 变为 false 时，渲染器调用离开钩子，钩子要给元素加减 class，读 el.classList，普通对象没有它，抛出 TypeError。同样，真正触发进入时也会抛错。第二项以为挂载就会碰 DOM。第三项把平台无关的“推迟 remove”和平台相关的“加减 class”混在一起：推迟 remove 的是 runtime-core，但钩子的实现在 runtime-dom。给自定义渲染器做动画，要从 BaseTransition 开始，自己写钩子。", "renderer",
      "<Transition name=\"f\">\n  <div v-if=\"show\">hi</div>\n</Transition>"],
    ["组件第一次渲染 h('div', { class: 'box', id: 'a' })，第二次渲染 h('div', { id: 'b' })。第二次渲染时，自定义渲染器的 patchProp 依次收到哪些调用？", ["patchProp(el, 'class', 'box', null)，然后 patchProp(el, 'id', 'a', 'b')","patchProp(el, 'id', 'a', 'b')，然后 patchProp(el, 'class', 'box', null)","只有 patchProp(el, 'id', 'a', 'b')，class 没有变化所以保留","先 remove 旧 div，再 createElement 并 patchProp 设置 id"], "更新属性时，Vue 先处理旧 props 里有、新 props 里没有的键，调用 patchProp(el, key, 旧值, null) 删除它；再处理新 props，值变了的键调用 patchProp(el, key, 旧值, 新值)。所以先删 class，再改 id。第三项忘了 class 在新 props 里消失了，不会被保留。第四项把更新当成了重建：元素类型和 key 都没变，不会重建。", "renderer"],
    ["模板里写 <div :foo.prop=\"1\">，渲染到真实的 DOM 后，哪一项正确？", ["div.foo 是 1，元素上没有 foo attribute","元素上有 foo=\"1\" 的 attribute，div.foo 是 undefined","div.foo 是 1，元素上同时有 foo=\"1\" 的 attribute","编译报错：foo 不是 div 的合法属性"], "编译器把 :foo.prop 的 key 改写成 \".foo\"，patchProp 看到点号开头，直接走“设为 DOM 属性”，去掉点号后执行 el.foo = 1，不写 attribute。没有 .prop 时，div 上没有 foo 这个属性，默认规则 key in el 为假，才会写成 attribute（第二项）。第三项以为 Vue 总会把两种都写：只有 value、checked、selected 这类特殊属性才会同步到 attribute。", "renderer"],
    ["自定义渲染器渲染 h('span', 'hello')。nodeOps 里哪个函数负责让 hello 出现在 span 里？", ["setElementText(span, 'hello')","createText('hello')，再 insert 到 span 里","patchProp(span, 'textContent', null, 'hello')","setText(span, 'hello')"], "元素的子节点只有文字时，Vue 不创建文本节点，直接调用 setElementText。只有混排的子节点（例如 [h('b'), 'tail']）才用 createText 创建文本节点。setText 用来更新一个已经存在的文本节点的内容，span 里没有文本节点。所以自己的 nodeOps 必须两种都处理。", "renderer"],
    ['在 Vue 3 中运行下面的模板。结果是什么？', ['v-if 先运行，读取 u 时报错', 'v-for 先运行，只列出 active', '显示全部用户，v-if 被忽略', '编译失败，不能写在同一元素上'], 'Vue 3 中 v-if 的优先级更高。v-if 运行时还没有循环变量 u，所以读取 u.active 报错。v-for 先运行是 Vue 2 的行为。v-if 没有被忽略。编译器允许这种写法，所以错误在运行时出现。把 v-for 放在外层的 <template> 上，或先用 computed 过滤。', 'migrate',
      '<li v-for="u in users" v-if="u.active">{{ u.name }}</li>'],
    ["store 用 byId 和 ids 存放任务。remove 只删了 byId 里的项，没有改 ids。看板用 ids.map(id => byId[id]) 渲染，并读取 task.title。删除一个任务后会怎样？", ["渲染 TaskCard 时读取 undefined 的 title，产生 TypeError，Vue 把它交给 errorHandler","任务从列表中消失，因为 byId 里已经没有它","列表照常显示这个任务，因为 ids 里还有它的 id","什么也不会发生，Vue 会自动同步 byId 和 ids"], "byId 和 ids 是两份需要同步的数据，这就是规范化的代价。只删 byId 时，ids 里还留着这个 id，byId[id] 是 undefined，读取它的 title 会产生 TypeError：Vue 捕获渲染里的错误并交给 app.config.errorHandler（没有配置就在控制台报错），这张卡片渲染为空。以为任务会消失的选项，忘了列表是由 ids 驱动的。以为列表照常显示的选项，忘了数据已经不在 byId 里。Vue 不会同步两份数据。修复：remove 里同时删除 byId 的项，并过滤 ids；并为 remove 写一个测试。", "project",
      "function remove(id) {\n  delete byId.value[id]\n}\n// 模板：<TaskCard v-for=\"id in ids\" :key=\"id\" :task=\"byId[id]\" />"],
    ["性能测试想断言“移动一个任务时，TaskCard 更新 0 次”。BoardView 渲染全部三列，每张卡片只显示自己的 title，不读 status。测试用全局 mixin 在 updated 里计数，没有区分组件。看板有 50 张卡片，移动一个任务（只改它的 status）后，updates 是多少？", ["1，BoardView 自己更新了一次，卡片都没有更新","0，卡片都没有更新","50，所有卡片都更新了","2，被移动的卡片更新了两次"], "全局 mixin 作用于每一个组件，包括 BoardView。移动任务后，列的选择器变了，BoardView 重新渲染，它的 updated 被调用一次。卡片的 props 是同一个响应式对象，卡片又不读 status，所以没有任何卡片更新，总数是 1。要断言卡片 0 次，必须在计数时过滤组件名，例如检查 this.$options.__name 是 TaskCard。以为是 0 的选项，没有想到 mixin 也计入了父组件。以为是 50 的选项，误认为列表变化时所有子组件都更新。", "project",
      "let updates = 0\nmount(BoardView, {\n  global: { plugins: [pinia], mixins: [{ updated() { updates++ } }] }\n})\nawait flushPromises()\nupdates = 0\nstore.move(10, 'doing')\nawait flushPromises()\nconsole.log(updates)"],
    ["看板的 `load()` 被连续点了两次“重试”。第一次请求慢（2 秒），第二次快（0.2 秒），两次返回的任务不同。store 是下面这样写的。所有请求结束后，`ids` 是什么？", ["第二次返回的任务，因为第一次的结果被 loadToken 丢弃了","第一次返回的任务，因为它先发出","两次结果合并，因为每次都写入 ids","空数组，因为两次请求互相取消"], "每次调用 `load` 先把 `loadToken` 加 1，并记下自己的编号。响应回来时编号和当前的 `loadToken` 不一样，说明后面又有新的 `load` 发出了，这次的结果直接丢弃。第一次的响应 2 秒后才到，此时 `loadToken` 已经是 2，它被丢弃，`ids` 保持第二次的结果。以为第一次的结果会留下的选项，把“先发出”当成了“该保留”。以为会合并的选项，忘了每次都是整体替换。没有任何地方取消请求，请求都会正常完成。", "project",
      "let loadToken = 0\nasync function load() {\n  const token = ++loadToken\n  const list = await api.listTasks()\n  if (token !== loadToken) return\n  ids.value = list.map(t => t.id)\n}"],
    ["路由表是 `{ path: '/task/:id', props: route => ({ id: Number(route.params.id) }) }`，没有给 id 参数加正则。用户打开 `/task/abc`，详情页会怎样？", ["id 是 NaN，接口请求 /api/tasks/NaN，得到 404，页面显示“任务不存在”，而不是 404 页","路由不匹配，显示 404 页","Number(\"abc\") 抛出错误，页面崩溃","路由忽略这个地址，停留在上一页"], "`/task/:id` 匹配任何非空的一段，`abc` 也匹配。`Number(\"abc\")` 不抛错，返回 NaN，详情页拿着 NaN 去请求 `/api/tasks/NaN`，假后端的路径正则只认数字，返回 404，详情页显示“任务不存在”。用户要的是 404 页，却得到一个看起来像“任务被删了”的提示。修复：路径写成 `/task/:id(\\\\d+)`，`abc` 不再匹配，落到兜底路由。以为会显示 404 页的选项，混淆了“路由不匹配”和“接口 404”。", "project",
      "const routes = [\n  { path: '/task/:id', component: Detail,\n    props: route => ({ id: Number(route.params.id) }) },\n  { path: '/:pathMatch(.*)*', component: NotFound }\n]"],
    ["用户在 `/task/1` 的详情页里把标题改成“新标题”但没有保存，点“下一个”去 `/task/2`。详情页同时注册了 `onBeforeRouteLeave` 和 `onBeforeRouteUpdate`，两个都是 `() => !dirty.value || window.confirm('有未保存的修改，确定离开？')`。用户在询问框里点“取消”。发生了什么？", ["导航被取消，页面仍是 /task/1，草稿“新标题”还在输入框里","导航继续，进入 /task/2，草稿丢失","导航继续，进入 /task/2，草稿保留在输入框里","抛出错误，因为守卫返回了 false"], "`/task/1` 到 `/task/2` 复用同一个组件，触发的是 `onBeforeRouteUpdate`。守卫返回 false（confirm 点取消得到 false，`!dirty || false` 为 false）会取消这次导航，地址和页面都不变，组件没有被更新，输入框里的草稿原样保留。以为会进入下一页的选项，忘了守卫返回 false 就是取消。返回 false 是取消导航的正常方式，不抛错。", "project"],
    // 第 9 版补充：每章至少 2 题（追加在末尾，已有题号和作答记录不变）
    ['计数器的文字在 count > 5 时变红。用 Vue 的声明式写法，你需要写什么？', ['在模板中写 :style 规则，代码只改 count', '在 click 中判断 count，再改 style.color', '在 click 中用 querySelector 改颜色', '修改 count 后，再调用一次 mount()'], '声明式写法中，模板说明“数据是这样时页面是什么样”。你只修改 count，Vue 按模板修改文字和颜色。判断后改 style.color、调用 querySelector，都是命令式写法。这时你自己修改 DOM，漏改一处，页面就出错。mount() 只调用一次。数据改变后，Vue 自动更新页面，不需要再次挂载。', 'first'],
    ['运行下面的代码后，#app 元素中是什么？', ['只有 <p>你好</p>，旧内容被清空', '“加载中…”和 <p>你好</p>', '<p>你好</p> 替换了 #app 本身', '仍是“加载中…”，要再调用 render()'], 'mount(\'#app\') 把应用挂载到 #app 中。Vue 先清空容器的内容，再插入渲染结果。所以“加载中…”消失，只剩 <p>你好</p>。#app 元素本身保留。替换容器是 Vue 2 的行为，Vue 3 不这样做。mount 立即渲染，不需要再调用其他函数。', 'first',
      '<div id="app">加载中…</div>\n\ncreateApp({\n  setup() {\n    const msg = ref(\'你好\')\n    return { msg }\n  },\n  template: \'<p>{{ msg }}</p>\'\n}).mount(\'#app\')'],
    ['useMouse 返回一个 reactive 对象，组件解构了它。鼠标移动后，模板中的 x 会怎样？', ['一直显示 0，x 只是当时的数字', '跟随鼠标变化，pos 是响应式的', '跟随鼠标变化，但要等下一帧', '报错，reactive 对象不能解构'], '解构 reactive 对象时，x 得到当时的值 0。之后修改 pos.x，局部变量 x 不变，所以页面一直显示 0。pos 是响应式的，但解构出来的数字不是。Vue 不会在下一帧补上更新。解构本身不报错。所以组合式函数的约定是：返回包含 ref 的普通对象。例如 return toRefs(pos)。这样调用者可以安全解构。', 'composables',
      'function useMouse() {\n  const pos = reactive({ x: 0, y: 0 })\n  // 鼠标移动时修改 pos.x 和 pos.y\n  return pos\n}\nconst { x } = useMouse()   // 模板：{{ x }}'],
    ['插件执行 app.config.globalProperties.$fmt = fmt。下面哪里可以直接使用 $fmt？', ['模板中，以及选项式 API 的 this 上', '所有 .js 文件中，像全局变量一样', '只在 ' + S + ' 中可以直接调用', '只在根组件中，子组件要 inject'], 'globalProperties 中的属性加到每个组件实例的代理上。模板通过这个代理读取数据，所以模板中可以写 {{ $fmt(price) }}。选项式 API 中写 this.$fmt。' + S + ' 和 setup() 中没有这个代理，所以不能直接使用它。要用 provide/inject，或直接 import。它不是 JavaScript 全局变量。它属于整个应用，所有组件都能用，不需要 inject。', 'app'],
    ['用户勾选了第一个复选框。picked 的值是什么？', ['[\'a\']，数组中加入它的 value', 'true，复选框只有真和假', '\'a\'，替换为它的 value', '[\'on\']，使用默认的 value'], 'v-model 绑定数组时，勾选的复选框把 value 加入数组。取消勾选时，删除它。所以结果是 [\'a\']。只有绑定的不是数组时，复选框才使用 true 和 false。数组不会被替换为单个字符串。这里写了 value 属性，所以不使用浏览器默认的 \'on\'。', 'forms',
      'const picked = ref([])\n// 模板\n<input type="checkbox" value="a" v-model="picked">\n<input type="checkbox" value="b" v-model="picked">'],
    ['Vue 2 中，给已有对象添加新属性要写 this.$set(this.obj, \'b\', 2)。在 Vue 3 的选项式 API 中怎样写？', ['直接赋值：this.obj.b = 2', '仍写 this.$set(this.obj, …)', '改写 Vue.set(this.obj, …)', '先在 data 中声明 b，再赋值'], 'Vue 3 用 Proxy 实现响应式。Proxy 能拦截新属性的添加，所以直接赋值就会更新页面。Vue 3 删除了 this.$set 和全局的 Vue.set。调用 this.$set 会报错：它不是函数。预先声明 b 是 Vue 2 的限制。Vue 2 用 Object.defineProperty，只能跟踪已有的属性。', 'migrate'],
    ["父组件 App 渲染子组件 Child，并给它传 :list=\"list\"。下面的代码让 App 重新渲染（other 变化），list 是 ref 且没有改变。Child 的渲染函数会运行吗？", ["不会。list 是同一个引用，shouldUpdateComponent 返回 false","会。父组件重新渲染时所有子组件都重新渲染","会。App 每次渲染都创建了新的 vnode","不会。Child 的 vnode 根本没有创建"], "App 的渲染函数运行，Child 的新 vnode 确实被创建（所以第四项错，第三项描述的事实不是更新的原因）。patch 到它时，shouldUpdateComponent 逐个用 !== 比较 props，list 是同一个引用，没有变化，返回 false，Child 的渲染函数不运行。", "runtime",
      "// App 的模板\n// <Child :list=\"list\" />\n// <p>{{ other }}</p>\nother.value++"],
    ["下面的子组件 setup 读取了 x.value 并保存。x 之后改变，页面会怎样？原因是什么？", ["不更新。setup 运行时不收集依赖，渲染函数里读的只是一个普通数字","更新。渲染函数里用到了 v，v 来自 x","更新。setup 会随 x 的变化重新运行","报错。setup 里不能读取 ref"], "setup 在 mountComponent 的第二步运行，Vue 暂停了依赖收集，并且 setup 只运行一次。渲染函数读到的 v 是当时的快照，没有读取 x，所以 x 不是渲染副作用函数的依赖。要让它随 x 变化，在渲染函数里读 x.value。", "runtime",
      "const Child = {\n  setup() {\n    const v = x.value\n    return () => h('i', v)\n  }\n}"],
    ["Middle 是 Parent 的子组件。Middle 的 setup 里先 provide('k', 'dark')，再 inject('k', 'none')。Parent 提供了 k 的值 'light'。Middle 里 inject 得到什么？", ["'light'","'dark'","'none'","undefined 并给出警告"], "inject 从父组件的 provides 开始查找，所以读不到组件自己提供的值，读到 Parent 的 'light'。Middle 提供的 'dark' 只对它的后代可见。默认值 'none' 只在整条原型链上都找不到时才用。", "runtime"],
    ["三个组件 App、Parent、Child 嵌套，各自在 setup 里注册 onBeforeUnmount 和 onUnmounted，打印自己的名字加 bum 或 um。卸载 Parent（含 Child）。Child 的 um 和 Parent 的 bum 谁先打印？", ["Parent bum 先，Child um 后","Child um 先，Parent bum 后","顺序不确定，取决于注册顺序","同时打印"], "unmountComponent 开头同步调用本组件的 bum，然后才卸载子树。所以 Parent bum、Child bum 都在 DOM 移除之前。um 被放进后置队列，在整棵子树卸载之后才运行。所以 Parent bum 先于 Child um。", "runtime"],
    ["子组件 Child 声明了 emits: ['save']，父组件每次渲染都传一个新的回调 onSave（回调里读取当次渲染时的 k）。k 先变成 1，再变成 2，两次更新后子组件调用 emit('save')。回调读到的 k 是多少？", ["2：Child 不更新，但 instance.vnode 换成了最新的 vnode，emit 从它的 props 里找回调","0：Child 没有更新，一直用第一次渲染时的回调","1：只有第一次更新换了 vnode","不确定：取决于 Child 有没有重新渲染"], "已声明的事件监听不参与 shouldUpdateComponent 的比较，所以 Child 没有重新渲染。但 updateComponent 在不更新的分支里仍然执行 instance.vnode = n2，把组件记录的 vnode 换成最新的。emit 从 instance.vnode.props 里找 onSave，所以每次都调用最新的回调，读到 2。第二项以为不更新就什么都不换。第三项以为只有第一次换。在 Vue 3.5.43 上实测输出 2。", "runtime",
      "const Child = { emits: ['save'], setup(p, { emit }) { saveFn = emit; return () => h('i') } }\n// 父组件：return () => { const k = n.value; return h(Child, { onSave: () => log.push(k) }) }\nn.value = 1; await nextTick()\nn.value = 2; await nextTick()\nsaveFn('save')   // log 里是什么？"],
    ["父组件把 count 传给 Child，count 从 0 变成 1。Child 在 onBeforeUpdate 里读取两样东西：props.count，以及自己当前根元素 DOM 里显示的文字。分别是什么？", ["props.count 是 1（已更新），DOM 文字还是 0（还没 patch）","props.count 是 0，DOM 文字是 0：钩子在一切更新之前运行","props.count 是 1，DOM 文字是 1：此时 DOM 已经更新","props.count 是 0，DOM 文字是 1"], "更新分支的顺序是：先 updateComponentPreRender（用 instance.next 更新 props），再调用 bu 钩子，再渲染并 patch 新子树。所以 onBeforeUpdate 里 props 已经是新的，DOM 还是旧的。第二项忽略了 props 更新在钩子之前。第三项是 onUpdated 的情形。在 Vue 3.5.43 上实测：props.count=1，DOM 文字 0。", "runtime",
      "const Child = {\n  props: ['count'],\n  setup(p) {\n    onBeforeUpdate(() => log(p.count, getCurrentInstance().subTree.el.textContent))\n    return () => h('i', String(p.count))\n  }\n}\n// 父组件：return () => h(Child, { count: cnt.value })\ncnt.value = 1"],
    ["Parent 渲染两个兄弟子组件 A 和 B。三个组件各在 setup 里注册 onBeforeMount 和 onMounted，打印名字加 bm 或 m。挂载完成后，日志顺序是什么？", ["P bm, A bm, B bm, A m, B m, P m","P bm, A bm, A m, B bm, B m, P m","A bm, B bm, P bm, A m, B m, P m","P bm, P m, A bm, A m, B bm, B m"], "bm 在每个组件的挂载分支开头同步调用，按进入组件的顺序：父先，然后 A、B。m 放进后置队列，要等到各自的子树 patch 完才入队：A 先完成，B 再完成，Parent 最后完成，队列在整棵树挂载后按入队顺序运行：A m, B m, P m。第二项以为 m 在组件挂载完立刻运行。第三项以为 bm 也是子先父后。在 Vue 3.5.43 上实测与第一项一致。", "runtime"],
    ["Parent 把 count 传给 Child，Child 的渲染函数同时读取 props.count 和自己的 own。同一轮同步代码里执行 cnt.value++ 和 own.value++。更新结束后，Child 的渲染函数一共运行几次（含初始渲染）？", ["2 次：父组件先更新并同步更新 Child，Child 自己排的更新任务运行时发现不脏，跳过","3 次：Child 被父组件更新一次，自己的更新任务又运行一次","2 次：因为两次修改被合并成同一个任务","1 次：初始渲染之后不会再运行"], "cnt 的变化让 Parent 的更新任务入队，own 的变化让 Child 的更新任务入队，Parent 的 id 小，先运行。Parent 的 patch 发现 count 变了，用 shouldUpdateComponent 判定需要更新，同步运行 Child 的渲染副作用函数（这次渲染同时读到新的 count 和 own）。随后轮到 Child 自己的更新任务：它是 runIfDirty，副作用函数已经不脏，什么也不做。所以共 2 次。第二项没考虑 runIfDirty。第三项结果对，但理由错：两个任务属于两个组件，没有合并，是父组件的同步更新让第二个任务落空。在 Vue 3.5.43 上实测 2 次。", "runtime"],
    ["父组件把 v-model 绑定到一个值为 undefined 的 ref。子组件在初始渲染后显示什么，父组件的 a 是什么？", ["子组件显示 x，a 仍是 undefined","子组件显示 x，a 也变成 x","子组件显示空白，a 仍是 undefined","报错：v-model 的值不能是 undefined"], "defineModel 的 default 只补子组件看到的值，不会写回父组件。所以子组件显示 x，父组件的 a 仍是 undefined，两边不一致。要让两边一致，让父组件自己给初值。a 变成 x 需要子组件写入 model.value，这里没有写入。undefined 是合法的 prop 值，不报错。", "api-design",
      "<script setup>\nconst model = defineModel({ default: 'x' })\n</script>\n<template><b>{{ model }}</b></template>\n\n<!-- 父组件 -->\n<!-- const a = ref(undefined) -->\n<!-- <Child v-model=\"a\" /> -->"],
    ["scope.stop() 之后，tick 还会运行吗？", ["会继续运行：onUnmounted 在组件之外没有注册回调（开发环境有警告）","不会：scope.stop() 清除所有定时器","不会：effectScope 里的 onUnmounted 等同于 onScopeDispose","报错：scope.run 里不能调用生命周期钩子"], "onUnmounted 属于组件实例，不属于 effectScope。在组件之外调用，Vue 只给出警告，回调不会注册。所以 clearInterval 没有被调用，定时器继续运行。组合式函数里的清理要写 onScopeDispose：它在组件卸载和 scope.stop() 时都会运行。scope.stop() 只停止 scope 内登记的 watch 和 watchEffect（computed 不登记在 scope 里），不会清除定时器。", "api-design",
      "export function useInterval(fn, ms) {\n  const id = setInterval(fn, ms)\n  onUnmounted(() => clearInterval(id))\n}\n\nconst scope = effectScope()\nscope.run(() => useInterval(tick, 1000))\nscope.stop()"],
    ["页面开头有一个按钮，后面是下面这组标签，再后面还有一个按钮。用户从页面开头一直按 Tab，焦点在这组标签上停几次？", ["1 次，停在第 3 个标签","5 次，每个标签各停一次","1 次，停在第 1 个标签","0 次，没有 tabindex=\"0\" 的元素会被跳过"], "roving tabindex 让组内只有一个元素的 tabindex 是 0，其余是 -1。tabindex=\"-1\" 的元素不在 Tab 顺序里，但可以用 focus() 聚焦。active 是 2，所以 Tab 只停在第 3 个标签上。再按 Tab 就离开这组标签。组内用方向键移动。第一项错在把组内每个元素都当作停靠点，那样 5 个标签会占 5 次 Tab。", "api-design",
      "<!-- const tabs = ['a', 'b', 'c', 'd', 'e'];  const active = ref(2) -->\n<button v-for=\"(t, i) in tabs\" :key=\"t\"\n        :tabindex=\"i === active ? 0 : -1\">{{ t }}</button>"],
    ["按 End 键之后，active 是多少？", ["1","2","3","0"], "End 调用 move(options.length, -1)，即 move(3, -1)。先减 1 得到 2，options[2] 是 disabled，继续减 1 得到 1。options[1] 不是 disabled，所以返回 1。返回 2 会停在不可用的选项上。3 是越界的下标。0 是第一项，Home 才去那里。", "api-design",
      "const options = [{ label: 'A' }, { label: 'B' }, { label: 'C', disabled: true }]\n\nfunction move(from, step) {\n  const n = options.length\n  let i = from\n  do { i += step } while (i >= 0 && i < n && options[i].disabled)\n  return i >= 0 && i < n ? i : from\n}\n\nactive = move(options.length, -1)"],



    ["购物车角标要显示商品总数。下面的写法里，除了 `setItems`，别的地方（例如加入商品、删除商品）也会修改 `items`。这时最容易出什么问题？", ["`count` 是独立的 `ref`，每个修改 `items` 的地方都要记得同步它","`items` 是 `ref`，数组变化后不会触发更新","`count` 用了 `computed`，所以每次读取都重新遍历数组","`setItems` 没有返回值，调用方拿不到结果"], "`count` 能由 `items` 算出来，却被存成独立的状态。每多一个修改 `items` 的地方，就多一个要同步的地方，漏一处就不一致。应该写成 `computed(() => items.value.reduce((n, i) => n + i.qty, 0))`。`ref` 数组的变化会触发更新。`computed` 有缓存，依赖不变时不会重新遍历。返回值与这个问题无关。", "state-arch",
      "const items = ref([])\nconst count = ref(0)\nfunction setItems(list) {\n  items.value = list\n  count.value = list.reduce((n, i) => n + i.qty, 0)\n}"],
    ["用户在搜索页输入关键字时，每输入一个字符，代码调用一次 `router.push({ query: { q } })`。用户搜索完想回到上一个页面，会遇到什么问题？", ["要按很多次后退，因为每个字符都产生了一条历史记录","地址栏里的 q 参数会丢失","页面刷新后搜索词不会保留","路由组件会被销毁并重新创建"], "`push` 每次都添加一条历史记录，输入 5 个字就有 5 条，后退要按很多次。连续输入应该用 `router.replace`，只替换当前这一条。地址栏的 q 保持最新，刷新后也能保留，这正是放进 URL 的好处。同一路由只改 query 时，组件通常被复用，不会重新创建。", "state-arch"],
    ["两个 setup store 在顶层互相调用对方，并读取对方的 state 作为初始值。先调用 `useA()`，再调用 `useB()`，运行结果是什么？", ["不报错，但在 A 的 setup 里创建出来的 B，读到的 A 的 `x` 是 `undefined`","立刻抛出“循环依赖”错误","两个 store 都读到对方的初始值","浏览器栈溢出，页面卡死"], "Pinia 在运行 setup 之前就登记了 store，所以循环调用不会无限递归，也不会抛错。`useA()` 运行 A 的 setup，期间 `useB()` 创建 B；B 的 setup 里再调用 `useA()`，拿到的是尚未创建完的 A，顶层读它的 state 得到 `undefined`，所以 `useB().init` 是 `undefined`，而 `useA().init` 是 2。把读取放进 `computed` 或 action，等两个 store 都创建完再读，才能得到正确的值。", "state-arch",
      "const useA = defineStore('a', () => { const b = useB(); const x = ref(1); const init = b.x; return { x, init } })\nconst useB = defineStore('b', () => { const a = useA(); const x = ref(2); const init = a.x; return { x, init } })\nuseA(); useB()"],
    ["任务列表来自接口。几个组件各自在 `onMounted` 里请求，并把结果写进 Pinia 的 `tasks`。哪一项最准确地描述了它的缺点？", ["每个组件都发请求，没有缓存、去重和失效机制，要自己写","Pinia 不能保存数组","`onMounted` 里不能使用 `await`","请求结果不能是响应式的"], "任务列表的真相在服务器，客户端持有的是会过期的缓存。管理缓存需要去重、失效、重试和乐观更新，这些要自己手写。请求缓存库（如 TanStack Query 的 Vue 版、Pinia Colada）已经提供了这些能力。Pinia 可以保存数组。`onMounted` 的回调可以是异步函数。写进 `ref` 的结果当然是响应式的。", "state-arch"],
    ['下面的代码运行结束后，n 是多少？', ['2', '1', '0', '3'], 'Child 的模板是 {{ state }}，这会遍历整个对象，把 a 和 b 都变成它的依赖。所以 b++ 触发一次更新，a++ 再触发一次，n 是 2。以为是 1 的选项，误认为组件只依赖显示出来的某个字段，可是 {{ state }} 读取了所有字段。以为是 0 的选项，忘了更新钩子在每次更新后运行。修复：只显示需要的字段，例如 {{ state.a }}。', 'perf-clinic',
      'const state = reactive({ a: 0, b: 0 })\nlet n = 0\nconst Child = {\n  setup() { onUpdated(() => n++); return { state } },\n  template: \'<p>{{ state }}</p>\'\n}\ncreateApp(Child).mount(el)\nstate.b++; await nextTick()\nstate.a++; await nextTick()\nconsole.log(n)'],
    ['用户反馈：“第一次打开页面要白屏四秒，之后点什么都很流畅。”应该首先看什么？', ['LCP，以及构建输出和 Network 面板里的 JS 体积', 'INP，以及子组件的更新次数', 'CLS，以及图片有没有设置宽高', '堆快照里的 Detached 元素'], '症状只出现在第一次加载，之后流畅。这说明问题在加载，不在交互：LCP 衡量最大内容出现的时间，首屏 JS 太大是常见原因。INP 和更新次数对应“点了之后卡”，这里点击是流畅的。CLS 对应内容跳动，症状里没有。堆快照对应用得越久越卡，也不符合。', 'perf-clinic'],
    ['useResize 在一个会反复显示和隐藏的组件里使用。组件被挂载并卸载了 5 次，现在页面上没有它。再触发一次 window 的 resize 事件，calls 是多少？', ['5', '0', '1', '4'], 'addEventListener 属于 window，不属于组件，组件卸载时 Vue 不会移除它。每次挂载都创建一个新的回调并注册，5 次挂载留下 5 个监听器，所以 calls 是 5。以为是 0 的选项，误认为卸载会自动清理。以为是 1 的选项，误认为同一个函数只注册一次，可是每次挂载的回调是新的闭包。修复：保存回调，在 onUnmounted 里调用 removeEventListener。', 'perf-clinic',
      'function useResize(cb) {\n  window.addEventListener(\'resize\', cb)\n}\n// 组件 setup：useResize(() => calls++)\n// 组件被挂载并卸载 5 次后：\nwindow.dispatchEvent(new Event(\'resize\'))\nconsole.log(calls)'],
    ["下面的代码运行后，`cb` 被调用几次？", ["1 次，只有 ① 触发","0 次","2 次","1 次，只有 ② 触发"], "deep: 2 让 traverse 只遍历两层：d 的属性 a，和 a 的属性 b。① 替换 `d.a.b`，读过 `a.b`，触发。替换后新的 b 对象只被当作叶子，它的 c 没有被读取。② 修改 `b.c`，没有依赖，不触发。所以共 1 次。选 2 次是忘了深度限制。选 0 次是以为 getter 只返回了 d，没有建立任何依赖：其实 traverse 会读取属性。", "watch-impl",
      "const d = reactive({ a: { b: { c: 1 } } })\nwatch(() => d, cb, { deep: 2 })\nawait nextTick()\nd.a.b = { c: 2 }       // ①\nawait nextTick()\nd.a.b.c = 3            // ②\nawait nextTick()"],
    ["父组件把 `x` 从 0 改成 1。控制台依次打印什么？", ["parent render、child watch 1、child render","parent render、child render、child watch 1","child watch 1、parent render、child render","parent render、child render"], "子组件的 pre 侦听器的更新任务带 pre 标记，id 是子组件的 uid。父组件的 patch 同步更新子组件时，`updateComponentPreRender` 先更新 props，再调用 `flushPreFlushCbs(instance)`，把属于这个子组件的前置任务取出来运行，然后子组件才渲染。所以侦听器在子组件渲染之前，并且已经看到新的 props。第二项把 pre 当成了 post。第四项忘了 props 变化会让侦听器运行。", "watch-impl",
      "const Child = {\n  props: ['x'],\n  setup(props) {\n    watch(() => props.x, v => console.log('child watch', v))\n    return () => { console.log('child render'); return h('i', props.x) }\n  }\n}\nconst Parent = {\n  setup() {\n    return () => { console.log('parent render'); return h(Child, { x: x.value }) }\n  }\n}\n// 挂载完成后：\nx.value = 1"],
    ["两个组件先后调用 `useShared()`。组件 A 卸载后，`created` 和 `disposed` 分别是多少？", ["1 和 0","1 和 1","2 和 1","2 和 0"], "共享状态只在第一次调用时创建，`created` 是 1。它住在 `effectScope(true)` 里，不属于任何一个组件，所以 A 卸载不会带走它。每个调用者在自己的作用域上登记一个 `dispose`，A 卸载只让计数从 2 减到 1，没有到 0，`scope.stop()` 不运行，`disposed` 仍是 0。选 1 和 1 是忘了引用计数。选 2 和 1 是以为每个组件都会再创建一份。", "watch-impl",
      "let users = 0, scope, state\nconst created = ref(0), disposed = ref(0)\nfunction useShared() {\n  users++\n  if (!state) {\n    scope = effectScope(true)\n    state = scope.run(() => { created.value++; onScopeDispose(() => disposed.value++); return ref(0) })\n  }\n  getCurrentScope() && onScopeDispose(() => { if (--users === 0) { scope.stop(); state = undefined } })\n  return state\n}\n// 组件 A 和组件 B 的 setup 里各调用一次 useShared()，然后 A 卸载"],
    ["下面两个侦听器依次创建，随后 n.value = 2，并等一个 tick。日志是什么？", ["b 1 undefined、a 2 1、b 2 1","a 2 1、b 1 undefined、b 2 1","b 1 undefined、b 2 1、a 2 1","a 2 undefined、b 2 undefined"], "immediate 的侦听器在创建时同步调用一次，新值是当前值 1，旧值是 undefined，所以 b 1 undefined 排第一。不带 immediate 的 a 在创建时就运行了 getter，把 1 记作旧值，所以第一次触发时旧值是 1，不是 undefined。两个侦听器都是 pre，按创建顺序在刷新里运行：a 2 1 在 b 2 1 之前。选最后一项的人以为不带 immediate 就没有旧值。", "watch-impl",
      "const n = ref(1)\nwatch(n, (v, o) => log('a ' + v + ' ' + o))\nwatch(n, (v, o) => log('b ' + v + ' ' + o), { immediate: true })\nn.value = 2"],
    ["id 先改成 2，等一个 tick，再改成 3，再等一个 tick，最后调用 stop()。日志是什么？", ["run 2、cleanup 2、run 3、cleanup 3","run 2、run 3、cleanup 2、cleanup 3","cleanup 2、run 2、cleanup 3、run 3","run 2、cleanup 2、run 3"], "清理函数在下一次回调之前运行：id 变成 3 时，先运行上一次登记的 cleanup 2，再运行回调 run 3。停止侦听器时，最后一次登记的 cleanup 3 也会运行。所以是 run 2、cleanup 2、run 3、cleanup 3。选第三项的人以为清理在回调之前登记。第四项忘了 stop 也会运行清理。", "watch-impl",
      "const stop = watch(id, (v, o, onCleanup) => {\n  log('run ' + v)\n  onCleanup(() => log('cleanup ' + v))\n})\nid.value = 2; await nextTick()\nid.value = 3; await nextTick()\nstop()"],
    ["组件的 setup 里按下面的顺序写。挂载完成后，日志的顺序是什么？", ["effect、setup end、render、post、mounted","setup end、render、effect、post、mounted","effect、post、setup end、render、mounted","setup end、effect、render、mounted、post"], "watchEffect 默认是 pre，第一次运行是同步的，就在 setup 里调用它的地方，所以 effect 最先。watchPostEffect 的第一次运行进后置队列，onMounted 的钩子也进后置队列，二者都在渲染之后；post 侦听器先入队，所以排在 mounted 前面。选第三项的人以为 watchPostEffect 也同步运行。", "watch-impl",
      "setup() {\n  watchEffect(() => log('effect'))\n  watchPostEffect(() => log('post'))\n  onMounted(() => log('mounted'))\n  log('setup end')\n  return () => { log('render'); return h('div') }\n}"],
    ["下面的代码执行后改变 src，哪些回调还会运行？", ["只有 C","A 和 C","B 和 C","全部都会运行"], "A 在 inner 里，inner 是 outer 的子作用域，outer.stop() 会带上它。B 是在 inner.run 结束之后创建的：run 结束后活动作用域恢复成 outer，所以 B 登记在 outer 里，也被停止。C 在 effectScope(true) 里，游离的作用域不属于 outer，不会停止。选 B 和 C 的人以为 inner.run 结束后活动作用域会丢失。", "watch-impl",
      "const outer = effectScope()\nouter.run(() => {\n  const inner = effectScope()\n  inner.run(() => watch(src, () => log('A')))\n  watch(src, () => log('B'))\n  effectScope(true).run(() => watch(src, () => log('C')))\n})\nouter.stop()\nsrc.value++"],
    ["同事的代码如下。父组件把 title 改了之后，子组件显示的标题没变。最可能的原因是什么？", ["title 在 setup 顶层被读出来存成了普通字符串，只算了一次","props 在 Vue 3.5 里不是响应式的","upper 是 computed，computed 的结果不会更新","子组件需要加 deep: true"], "`const upper = props.title.toUpperCase()` 在 setup 顶层运行，只运行一次，是快照。写成 `computed(() => props.title.toUpperCase())`，读取发生在被追踪的副作用函数里，就会更新。props 本身是响应式的，第二项错。第三项把写法弄反了：这里的 upper 是普通字符串，不是 computed。deep 只影响 watch。", "reactivity-pitfalls",
      "const props = defineProps(['title'])\nconst upper = props.title.toUpperCase()\n// 模板：<h2>{{ upper }}</h2>"],
    ["下面的 watchEffect 创建后，过一会儿依次执行 a.value++ 和 b.value++（每次之后等待下一轮更新）。回调一共运行几次（含第一次）？", ["2 次：第一次，加上 a 改变那次","3 次：每次改变都运行","1 次：只有第一次","2 次：第一次，加上 b 改变那次"], "a 在 await 之前读取，被收集；b 在 await 之后读取，没有被收集。所以 a 改变会重新运行，b 改变不会。共 2 次。第二项以为两个都被追踪。第四项把两个依赖弄反了。await 之后的读取不属于 watchEffect 同步运行的那一段。", "reactivity-pitfalls",
      "const a = ref(0), b = ref(0)\nwatchEffect(async () => {\n  const x = a.value\n  await Promise.resolve()\n  console.log(x, b.value)\n})"],
    ["组件在 setup 里写了下面的代码。组件卸载后，修改 id，哪个说法正确？", ["每次挂载都会多留下一个仍在运行的 watch，卸载后回调继续运行","Vue 在卸载时会停止它，回调不再运行","只有第一次挂载留下的 watch 会继续运行","会抛出错误，因为 setTimeout 里不能调用 watch"], "watch 登记到创建那一刻的当前组件。setTimeout 回调运行时没有当前组件，这个 watch 不属于任何组件，卸载时不会停止，每挂载一次就多一个。它不会抛错，所以问题很隐蔽。修复：在 setup 里创建 effectScope，用 scope.run 包住 watch，或保存 stop 在卸载时调用。", "reactivity-pitfalls",
      "setup() {\n  setTimeout(() => {\n    watch(id, load)\n  }, 100)\n}"],
    ["下面的代码输出什么？", ["2　[object Object]1","2　3","[object Object]1　[object Object]1","1　2"], "ref 放在 reactive 对象的属性里会自动解包，所以 `o.n` 是数字 1，加 1 得 2。放在数组里不会解包：`o.list[0]` 仍然是 ref 对象，和 1 相加时被转成字符串 `[object Object]`，结果是 `[object Object]1`。要写 `o.list[0].value + 1`。第二项以为数组里的 ref 也会解包。第三项以为属性里的也不解包。", "reactivity-pitfalls",
      "const o = reactive({ n: ref(1), list: [ref(2)] })\nconsole.log(o.n + 1, o.list[0] + 1)"],
    ["KeepAlive 的 max 是 1。A 已经显示，现在执行 cur.value = B。切换时，A 上会运行哪些钩子？", ["只运行 onUnmounted，没有 onDeactivated","只运行 onDeactivated，A 进入缓存","先运行 onDeactivated，再运行 onUnmounted","什么钩子都不运行，A 留在隐藏容器里"], "max 把正在显示的组件也算进名额。B 进入缓存后，keys 有 2 个，超过 1，最久没用的 A 被淘汰。A 恰好是当前正在显示的那一个，淘汰时 pruneCacheEntry 只清掉它的 KeepAlive 标记（resetShapeFlag），随后 patch 把 A 换成 B 时，A 就是一次普通卸载：运行 onUnmounted，不运行 onDeactivated。切回 A 时会创建新的实例，先 mounted 再 activated。选“只运行 onDeactivated”的人以为 A 被缓存了：缓存里已经没有它的位置。选“先 deactivated 再 unmounted”的人以为淘汰要经过失活，但被淘汰的当前组件没有走失活这条路。", "builtins-impl",
      "const hooks = (n) => {\n  onMounted(() => log(n + ' mounted'))\n  onActivated(() => log(n + ' activated'))\n  onDeactivated(() => log(n + ' deactivated'))\n  onUnmounted(() => log(n + ' unmounted'))\n}\nconst A = { setup() { hooks('A'); return () => h('i', 'A') } }\nconst B = { setup() { hooks('B'); return () => h('i', 'B') } }\nconst cur = shallowRef(A)\n// 根组件渲染：h(KeepAlive, { max: 1 }, [h(cur.value)])\ncur.value = B"],
    ["输入框在 Teleport 里，用户已经在里面输入了 hello。disabled 先变成 true，再变回 false。关于这个输入框，哪一项正确？", ["始终是同一个 DOM 元素，值仍是 hello，Box 的 onMounted 只运行过一次","每次切换都会创建新的 input，值被清空，Box 的 onMounted 运行三次","变成 true 时 input 被移回原位置但值被清空，变回 false 时再移走","变成 true 时 input 被销毁，变回 false 时用旧的值重新创建"], "Teleport 更新时发现 disabled 变了，不重新创建子节点，而是 moveTeleport：把已有的 DOM 移到新位置（true 时移回两个锚点之间，false 时移到目标容器）。同一个元素被搬来搬去，输入的值保留，组件实例也没有卸载，所以 onMounted 只运行一次。选“每次都创建新的”的人把 disabled 当成了 v-if。移动用的是 insertBefore，元素在新位置上仍是原来那一个。", "builtins-impl",
      "const Box = { setup() { onMounted(() => log('mounted')); return () => h('input') } }\nconst disabled = ref(false)\n// 根组件渲染：h('div', [h(Teleport, { to: '#modal', disabled: disabled.value }, [h(Box)])])\n// 挂载后：在 #modal 里的 input 中输入 hello\ndisabled.value = true\nawait nextTick()\ndisabled.value = false\nawait nextTick()"],
    ["下面的异步组件在页面上用了两处。loader 的前两次调用都失败，第三次成功。页面稳定之后，loader 被调用了几次？onError 收到的 attempts 依次是什么？", ["3 次；attempts 依次是 1、2","6 次；每个实例各自重试，attempts 依次是 1、2、1、2","3 次；attempts 依次是 0、1、2","1 次；重试只重新渲染，不再调用 loader"], "两个实例共用同一个 pendingRequest，重试也发生在这一条请求链上：每次失败只调用一次 onError。retry() 先清掉 pendingRequest 再重新 load()，所以重试是重新调用 loader。attempts 从 1 开始数，第一次失败收到 1，第二次失败收到 2，第三次 loader 成功，两处都显示 ok。共调用 3 次。选 6 次的人以为每个实例各管各的请求。选 0、1、2 的人以为 attempts 是已经重试的次数。选 1 次的人没看到 retry 会重新调用 loader。", "builtins-impl",
      "let calls = 0\nconst Real = { render: () => h('b', 'ok') }\nconst AC = defineAsyncComponent({\n  loader: () => {\n    calls++\n    return calls < 3 ? Promise.reject(new Error('net')) : Promise.resolve(Real)\n  },\n  onError(err, retry, fail, attempts) {\n    if (attempts <= 3) retry()\n    else fail()\n  }\n})\n// 根组件渲染：h('div', [h(AC), h(AC)])"],
    ["KeepAlive 里的组件 A 有 watch(src, cb)。切换到 B，A 进入缓存失活。之后 src 改变了。cb 会运行吗？", ["会运行：失活只是把 DOM 搬走，实例和侦听器都还在","不会运行：失活时侦听器被停止，激活时重新创建","不会运行，但激活时会补一次调用","会运行，但 cb 里读到的 DOM 已经被销毁"], "失活只做两件事：move 把 DOM 搬进隐藏容器，并把 onDeactivated 钩子放进后置队列。组件实例没有卸载，它的作用域和侦听器没有停，所以 src 改变时 cb 照常运行。第二项把失活当成了卸载。第三项没有这种补调用的机制。第四项错在 DOM 只是在隐藏容器里，没有被销毁。", "builtins-impl",
      "const A = { setup() { watch(src, v => log(v)); /* … */ } }\n// <KeepAlive><component :is=\"cur\" /></KeepAlive>\n// cur 从 A 切到 B 之后：src.value = 1"],
    ["Suspense 设置了 timeout=\"100\"，已经显示了 A 的内容。切换默认插槽的根组件为 B，B 的 setup 要 50 ms。切换期间页面显示什么？", ["一直是 A 的内容，直到 B 完成换成 B，fallback 没有出现","先显示 fallback，B 完成后换成 B","先显示 fallback 100 ms，然后换成 B","空白 50 ms，然后换成 B"], "切换根组件时，新内容在新的隐藏容器里等待，旧内容留在页面上。只有等待超过 timeout（100 ms）还没有完成，才显示 fallback。B 只要 50 ms，在 timeout 之前就完成了，所以直接从 A 换成 B，fallback 一次也没出现。第二项是首次加载的行为。第三项以为 fallback 总会出现并持续 timeout 的长度。第四项忘了旧内容一直在。", "builtins-impl"],
    ["Teleport 的目标 #t 是同一个模板里排在 Teleport 后面的元素。下面两种写法，挂载后分别怎样？", ["第一种警告找不到目标，内容没有渲染；第二种内容出现在 #t 里","两种都正常渲染到 #t","两种都警告找不到目标","第一种内容出现在原位置，第二种出现在 #t 里"], "没有 defer 时，Teleport 的 process 在挂载时同步查找目标。这时 #t 排在后面，还没有创建，Vue 警告 Failed to locate Teleport target，内容不渲染。defer 把挂载推迟到后置队列，等整棵树 patch 完再找目标，#t 已经存在，内容出现在其中。第四项以为找不到目标时会退回原位置：只有 disabled 才会就地渲染。", "builtins-impl",
      "// 写法一\n<div>\n  <Teleport to=\"#t\"><b>in</b></Teleport>\n  <section id=\"t\"></section>\n</div>\n// 写法二：同上，Teleport 加 defer\n<Teleport to=\"#t\" defer><b>in</b></Teleport>"],
    ['生产构建，应用设置了 app.config.errorHandler，没有任何 errorCaptured。组件 A 的 setup 抛出错误，模板是 <i>{{ x }}</i>（x 本应由 setup 返回）。页面上这个组件会怎样？', ['errorHandler 收到错误，组件仍然渲染，x 是 undefined，得到空的 <i></i>', 'errorHandler 收到错误，组件位置变成 <!---->', 'errorHandler 收到错误，组件被卸载，兄弟组件不受影响', 'errorHandler 收不到，因为 setup 不被 Vue 包装'], 'setup 抛错由 callWithErrorHandling 接住并交给 handleError，errorHandler 会收到。setup 没有返回值，Vue 继续完成组件的初始化并渲染模板，读不到 x，得到半空的界面。变成注释节点（第二项）是渲染函数抛错时的结果。', 'errors',
      'const A = {\n  setup() { throw new Error(\'x\'); return { x: 1 } },\n  template: \'<i>{{ x }}</i>\'\n}'],
    ['点击按钮时，哪个处理函数的错误不会到达 errorCaptured 和 app.config.errorHandler？', ['function go() { fetch(\'/api\').then(r => { throw new Error(\'bad\') }) }', 'function go() { return fetch(\'/api\').then(r => { throw new Error(\'bad\') }) }', 'async function go() { await fetch(\'/api\'); throw new Error(\'bad\') }', 'function go() { throw new Error(\'bad\') }'], '第一项启动了 Promise 但没有返回，Vue 拿不到它，拒绝只会触发 unhandledrejection。第二项返回了 Promise，第三项是 async 函数，第四项是同步抛错，Vue 都能接住。', 'errors',
      '<button @click="go">go</button>'],
    ['一个子组件在更新时渲染函数抛错，外层有 ErrorBoundary，它的 onErrorCaptured 记录错误并返回 false，但模板没有用 v-if 切换到后备界面（插槽一直显示）。点“重试”（只是 error.value = null）之后，这个子组件会怎样？', ['没有变化：它没有被卸载，仍然停在出错的 <!----> 状态，直到数据变化触发下一次成功渲染', '被卸载并重新挂载，恢复正常', '抛出新的错误到 errorHandler', '整个应用重新挂载'], '子树只有在被 v-if 切换卸载时，重试才等于重新挂载。这里插槽一直显示，子组件实例还在，只是上一次渲染结果是注释节点；清除错误不会触发它重新渲染。需要强制重建时，给子树加 key 并在重试时递增。', 'errors',
      'onErrorCaptured(err => { error.value = err; return false })\nconst retry = () => { error.value = null }\n// template: <slot />   // 没有 v-if'],
    ['router.beforeEach 里的异步守卫抛出错误。关于 router.onError 和 router.push() 返回的 Promise，哪一项正确？', ['onError 被调用，push 的 Promise 被拒绝，路由保持不变', 'onError 被调用，push 的 Promise 成功，返回 NavigationFailure', 'onError 不被调用，错误交给 app.config.errorHandler', 'onError 被调用，路由已经切换到目标页'], '守卫抛出的错误由路由自己处理：触发 onError，同时让 push 的 Promise 被拒绝，导航不会完成。NavigationFailure 是守卫返回 false 等“正常取消”的值。路由守卫不是 Vue 调用的，所以不经过 app.config.errorHandler。', 'errors'],
    ["下面的 remove 在删除第一项之后，会出现什么问题？", ["原来第 2 项的 touched 留在下标 1，现在下标 1 是原来的第 3 项，状态落到了别的项上","被删项的 touched 被正确清除，其余项不受影响","数组没有变化，因为 splice 不会触发响应式更新","所有项的 touched 都被清空"], "splice 只改了数组，按路径存的 touched 仍挂在原来的下标上。项一前移，状态就留在原地，落到下标相同的另一项上。同步错误是算出来的，所以会自己跟上；touched、异步错误、服务端错误是存下来的，要在数组操作里搬运。splice 会触发响应式更新，也不会清空其他项的状态。", "forms-arch",
      "const touched = reactive({})   // 'items[1].price' → true\nfunction remove(i) {\n  values.items.splice(i, 1)\n}\n// 用户碰过第 2 项的价格输入框（touched['items[1].price'] = true）\nremove(0)"],
    ["FormPage 的模板如下。rules 是组件外的常量数组，FormPage 自己没有读任何字段的值。用户在 email 字段里输入一个字符，哪些组件会更新？", ["只有 email 对应的 Field","email 对应的 Field 和 FormPage","全部三个 Field","全部三个 Field 和 FormPage"], "Field 通过路径只读自己的值，所以只有 email 的 Field 更新。FormPage 没有读字段的值，不依赖它。另外两个 Field 的 props 没有变（规则是同一个常量数组）。如果把 :rules=\"[required]\" 写成内联数组，FormPage 每次渲染都会生成新数组，子组件才会跟着更新；如果 FormPage 里读了 JSON.stringify(form.values)，FormPage 也会更新。", "forms-arch",
      "<!-- FormPage -->\n<Field name=\"name\" :rules=\"rules\" />\n<Field name=\"email\" :rules=\"rules\" />\n<Field name=\"phone\" :rules=\"rules\" />"],
    ["异步校验的 watch 如下。检查 ann 要 900 毫秒，检查 anna 要 200 毫秒。用户先输入 ann，100 毫秒后改成 anna。两个请求都返回之后，会怎样？", ["error 是“已被占用”，anna 的正确结果被 ann 的旧结果覆盖了","error 为空，因为 anna 是最后输入的","error 为空，因为 await 会按顺序恢复","watch 报错，因为同一个 watch 不能同时运行两次"], "两个回调互不相干，各自 await 自己的请求。anna 的结果先到，写入空字符串；ann 的结果后到，写入“已被占用”，覆盖了它。await 只管自己那一次，不会让两次回调按顺序恢复。修复：给每次检查领一个序号，回来时只有最新的序号可以写入，并且过期的结果也不能改 validating。", "forms-arch",
      "watch(name, async v => {\n  error.value = await checkName(v)   // ann 慢，anna 快\n})"],
    ["字段数组 items 有四项。用户碰过第 2、第 3 项的 name（touched 里有 'items[1].name' 和 'items[2].name'）。调用 move(3, 1)，把第 4 项移到第 2 个位置，并按 remap 搬运状态。搬运之后 touched 里有哪些键？", ["items[2].name 和 items[3].name","items[1].name 和 items[2].name","items[1].name 和 items[3].name","只剩 items[3].name"], "移动之后，原来的第 2、第 3 项分别后移一位，变成下标 2 和 3。touched 是按路径存的历史，必须跟着项搬运：键从 items[1].name、items[2].name 改成 items[2].name、items[3].name。新来的第 2 项（原第 4 项）没有被碰过，所以下标 1 没有键。第二项是没有搬运的结果，状态留在原下标，落到了别的项上。第三项只搬了一个。第四项以为移动会清空状态。", "forms-arch",
      "// values.items 原来是 [A, B, C, D]\n// touched：{ 'items[1].name': true, 'items[2].name': true }  （B 和 C 被碰过）\nform.array('items').move(3, 1)   // D 移到下标 1"],
    ["库的 `package.json` 如下。使用者为了少写一层路径，在代码里写 `import { MiniButton } from 'mini-ui/dist/components/MiniButton.js'`，这个文件确实在 tarball 里。会怎样？", ["Node 和打包器都拒绝（Node 抛出 ERR_PACKAGE_PATH_NOT_EXPORTED，Vite 等打包器也拒绝，只是报错信息不同），因为 exports 是封闭的，没写进去的路径不能导入","正常导入，`files` 里包含了 `dist`，路径存在就能用","正常导入，`exports` 只限制主入口 `.`，深层路径不受影响","只有 Node 拒绝，打包器会直接按文件路径读取"], "一旦写了 `exports`，只有里面列出的路径能被导入，其余路径（包括真实存在的文件）都会被拒绝。这让库作者可以随意重构 dist 的内部结构。第二项把 `files`（决定发布什么）和 `exports`（决定能导入什么）混为一谈。第三项以为 exports 只管主入口。第四项以为打包器不遵守 exports，实际上 Vite 等现代工具都遵守。", "lib",
      "{\n  \"files\": [\"dist\"],\n  \"exports\": {\n    \".\": { \"types\": \"./dist/index.d.ts\", \"default\": \"./dist/index.js\" },\n    \"./style.css\": \"./dist/style.css\"\n  }\n}"],
    ["库的 `MiniField` 用模块里的计数器生成输入框的 id。服务端渲染的服务运行了一段时间，浏览器水合时控制台出现不匹配警告。最可能的原因是什么？", ["模块级的 `uid` 在服务器进程里跨请求累加，第 N 个请求渲染出的 id 与浏览器从 0 开始数的 id 不一致","`defineModel` 在服务器上不能使用","`label` 的 `for` 属性不能用变量","服务器上 `uid++` 不会执行，所以 id 总是 `field-0`"], "服务器进程里的模块只加载一次，`uid` 在所有请求之间共享，越数越大；浏览器每个页面从 0 开始，两端的 id 不同。应该用 `useId()`：它按应用实例和组件位置生成，两端一致，每个请求都从头开始。第四项以为服务器不执行 setup，实际会执行。", "lib",
      "let uid = 0\n// MiniField 的 setup\nconst id = 'field-' + uid++"],
    ["库自带了一份 Vue（没有外部化）。应用的模板里读取库返回的 `n`，下面的代码在 Vue 3.5.43 里运行，`console.log` 输出什么？", ["true false","true true","false false","报错，两份 Vue 的对象不能互相检查"], "`isRef` 靠对象上的 `__v_isRef` 标记判断，不依赖哪一份 Vue，所以应用的 `isRef` 认得库的 ref，是 true。`reactive` 的代理缓存是每份 Vue 各自的 WeakMap，同一个对象在两份 Vue 里得到两个不同的代理，`===` 是 false。这正是两份 Vue 让人迷惑的地方：很多检查能通过，响应式却是断开的。", "lib",
      "// lib 里：import { ref, reactive } from 'vue'（库自带的那份）\nexport const libN = ref(0)\nexport const libReactive = reactive\n\n// 应用里：import { isRef, reactive } from 'vue'（应用的那份）\nconst o = {}\nconsole.log(isRef(libN), reactive(o) === libReactive(o))"],
    ["库的 `exports` 把 `default` 写在 `import` 前面。一个 ESM 应用写 `import { x } from 'mini-ui'`，Node 会加载哪个文件？", ["./dist/a.js，也就是 `default` 指向的文件","./dist/b.js，也就是 `import` 指向的文件，因为应用是 ESM","报错，条件的顺序不对","两个文件都加载，后者覆盖前者"], "`exports` 的条件按书写顺序匹配，第一个满足的胜出。`default` 对任何环境都满足，写在前面就永远先命中，后面的 `import` 轮不到。所以 `default` 要写在最后，`types` 要写在最前。第二项以为工具会挑“最合适”的条件。第三项：这种写法语法合法，不会报错，只是悄悄走了错误的文件。第四项：只会解析出一个目标。", "lib",
      "\"exports\": {\n  \".\": { \"default\": \"./dist/a.js\", \"import\": \"./dist/b.js\" }\n}"],
    ["`ErrorBoundary` 包着 `RouterView`，用 `onErrorCaptured` 记下错误并显示后备界面。用户在看板上看到后备界面后，点击导航去了另一个页面，后备界面还在。最可能漏了什么？", ["换页时没有调用边界的 reset，边界的 error 状态还是真","后备界面没有写 role=\"alert\"","onErrorCaptured 应该返回 true","RouterView 不能放在边界里面"], "边界在有错误时只渲染后备内容，换页后路由渲染的新页面被挡在后面，因为边界自己的 `error` 状态没有清掉。要在路由变化时调用 reset，把 `error` 置空，并且只在确实有错误时才重建子树（改变 key 会销毁整个子树，每次换页都重建会丢掉缓存的状态）。`role=\"alert\"` 只影响读屏软件。`onErrorCaptured` 返回 false 表示错误已处理，不再向上传递，返回 true 不会让后备界面消失。RouterView 可以放在边界里，这是常见做法。", "capstone"],
    ["对 1000 个任务的看板做了三处修改，每处单独做都能让一个指标变好。性能测试断言“移动一张已渲染的卡片，TaskCard 更新 0 次，BoardColumn 更新 2 次”。下面哪个修改撤销后，BoardColumn 的更新次数会变成 3？", ["把列的选择器改成每次都返回新数组（内容相同）","把 BoardColumn 的 key 去掉","去掉 KeepAlive","把每列显示的卡片数从 50 改成 100"], "已完成列的 ids 内容没变，但如果选择器每次重新计算都返回新数组，引用变了，`BoardColumn` 的 props 比较（`hasChanged`，也就是 `Object.is`）认为变了，已完成列也更新，次数变成 3。去掉 key 影响的是列表项的复用，这里三列是固定的。KeepAlive 影响的是返回看板时是否重新挂载，不影响一次移动里的更新。每列显示多少张影响 DOM 数量，不影响列的 props 是否变化。", "capstone",
      "function column(status) {\n  return computed(prev => {\n    const next = ids.value.filter(id => byId.value[id].status === status)\n    return prev && same(prev, next) ? prev : next   // 撤销这一行的“返回 prev”\n  })\n}"],
    ["为了让线上同一份看板代码既能在浏览器运行，也能在 Node 里服务端渲染，`router/index.ts` 原来是 `export default router`（模块里 createRouter 一次）。服务端同时处理两个用户的请求，下面哪个现象最可能出现？", ["一个用户的导航状态和另一个用户的请求共用同一个 router，当前路由互相覆盖","服务端报错，因为 createRouter 不能在 Node 里调用","水合时浏览器的 router 和服务端的 router 自动合并","没有问题，router 是只读的"], "服务端是一个长期运行的进程，模块只会加载一次，模块级的 router 被所有请求共用。`router.push(url)` 会修改它的当前路由，两个请求交错时，一个请求渲染到一半，当前路由被另一个请求改了，渲染出错的页面。每个请求都要自己造 app、router、pinia，所以导出工厂函数。`createRouter` 在 Node 里可以调用（用 memory history）。水合不会合并两端的 router，浏览器端有自己的实例。router 不是只读的，导航会改它。", "capstone",
      "// router/index.ts（改造前）\nexport default createRouter({ history, routes })\n// entry-server.ts\nexport async function render(url) {\n  router.push(url)\n  await router.isReady()\n  return renderToString(createSSRApp(App).use(router))\n}"],
    ["线 B 里，列只显示前 50 张，加“显示更多”。首屏 DOM 节点从 5446 降到 885。同时，第 23 章的性能测试仍然移动 id 为 500 的任务（1000 个任务全在待办列），测试通过。这个测试现在还能证明什么？", ["几乎什么也证明不了：id 500 没有被渲染，本来就不会有卡片更新","证明其他卡片更新 0 次，和以前一样","证明 BoardColumn 更新 2 次","证明 KeepAlive 生效"], "只显示前 50 张时，id 500 排在第 500 位，根本没有渲染成 TaskCard，移动它不会让任何卡片更新，测试永远通过。修改了被测代码的结构以后，测试的输入也要跟着改：换成一张已经渲染出来的任务（例如 id 4），并且让断言区分 TaskCard 和 BoardColumn。这也是“故意改坏看测试会不会变红”的用处：改回每次返回新数组，换了任务的测试会变红，旧的测试不会。", "capstone"],
    ["服务器对 `GET /api/orders` 返回 HTTP 500，响应体是 `{\"message\":\"boom\"}`。下面的代码运行后，`orders` 和 `error` 是什么？", ["`orders` 变成 `{ message: \"boom\" }`，`error` 仍是空，页面拿到了一个不是订单列表的数据","`orders` 保持空，`error` 是“网络错误”","`orders` 变成空数组，`error` 是 “500”","`fetch` 抛出 `HTTPError`，进入 catch"], "`fetch` 只有在没拿到响应时才抛错（断网、DNS 失败、被取消）。服务器返回 500 它照常返回 `Response`，`res.ok` 是 `false`，但代码没检查，直接 `res.json()`，把错误响应体当成了订单列表。所以 `error` 不会被设置，页面渲染时才会在奇怪的地方出错。请求层要检查 `res.ok`，把 HTTP 错误转成统一的错误。`fetch` 没有叫 `HTTPError` 的异常，axios 和 ofetch 才会替你对非 2xx 抛错。", "data-fetching",
      "const orders = ref([])\nconst error = ref(null)\nasync function load() {\n  try {\n    const res = await fetch('/api/orders')\n    orders.value = await res.json()\n  } catch {\n    error.value = '网络错误'\n  }\n}"],
    ["`id` 从 1 快速变成 2。请求 1 被 `abort()` 取消时，请求 2 还在路上。下面的写法在这一刻，页面状态是什么？", ["`loading` 是 `false`，`error` 是 `AbortError`，而请求 2 还没返回","`loading` 仍是 `true`，`error` 为空，等请求 2 返回","`loading` 是 `false`，`error` 为空，`data` 被清空","回调不会再运行，状态保持请求 1 开始时的样子"], "`abort()` 让请求 1 的 `await` 抛出 `AbortError`，落进 `catch`，把 `error` 设成这个错误；接着 `finally` 运行，`loading` 变成 `false`。此时请求 2 才刚发出，页面却显示“加载失败”且没有加载状态。被取消的请求不是错误，也不该碰状态：在 `catch` 和 `finally` 里先判断 `c.signal.aborted`，已取消就直接返回。第二项以为被取消的请求不会执行后续代码，其实 `catch` 和 `finally` 照常运行。", "data-fetching",
      "watch(id, async (v, _old, onCleanup) => {\n  const c = new AbortController()\n  onCleanup(() => c.abort())\n  loading.value = true\n  try {\n    data.value = await fetchUser(v, c.signal)\n  } catch (e) {\n    error.value = e\n  } finally {\n    loading.value = false\n  }\n})"],
    ["商品列表用查询库缓存。用户点“下一页”，`page` 从 1 变成 2，但列表仍然显示第 1 页的内容，网络面板里也没有新请求。最可能的原因是什么？", ["`queryKey` 里没有 `page`，第 2 页读到的还是 key 为 `['products']` 的同一个缓存条目","`page` 是 `ref`，查询库不能侦听 `ref`","`staleTime` 太短，缓存被立即清除了","`queryFn` 需要写成 `async`"], "缓存以 key 为单位。key 不变，查询库就认为是同一份数据，在新鲜期内直接用缓存，不会发新请求。`queryFn` 里读了 `page.value`，但那不是 key 的一部分，库不会因此重新取。把所有会影响结果的参数都放进 key：`['products', page]`（TanStack 里放 ref 本身，Colada 里用 getter）。`staleTime` 太短只会让请求更多，不会让它消失。`queryFn` 返回 Promise 即可，不需要 `async` 关键字。", "data-fetching",
      "const page = ref(1)\nconst { data } = useQuery({\n  queryKey: ['products'],\n  queryFn: () => request(`/products?page=${page.value}`)\n})"],
    ["令牌过期后，三个请求同时收到 401。请求层的做法是：每个 401 都调用 `refreshToken()` 换新令牌，再重发自己。服务器规定刷新令牌只能用一次，用过即作废。会发生什么？怎样修？", ["三个请求各自刷新，第一个成功后另外两个用已作废的刷新令牌失败，用户被误踢到登录页。让所有 401 共用同一个进行中的刷新 Promise","三个请求都刷新成功，只是多发了两次请求，没有问题","第一个刷新成功，另外两个请求自动使用新令牌，不需要处理","刷新应该放在页面的 `onMounted` 里，不能放在请求层"], "刷新令牌只能用一次时，三个并发的刷新里最多一个成功，其余的会失败，请求层把失败当成“登录已失效”，用户被无故踢出。修复是“单飞”：把进行中的刷新保存在模块变量里（`refreshing ??= doRefresh().finally(() => refreshing = null)`），后来的 401 等待同一个 Promise，成功后一起重发。第二项忽略了令牌只能用一次的前提。第三项没有任何机制让它们“自动”使用新令牌。刷新是请求层的职责，放进页面会让每个页面重复实现。", "data-fetching"],
    ["页面里有下面的代码，接口 `/api/count` 每次被调用都在服务器终端打印一行。用户直接在地址栏打开这个页面，接口一共被调用几次？", ["4 次：服务器上 3 次，浏览器水合时 1 次（只有直接写的 $fetch 在浏览器又执行了一遍）","3 次：都在服务器上，浏览器全部使用 payload","6 次：三个调用在两端各执行一次","1 次：同一个接口只请求一次"], "`useFetch` 和 `useAsyncData` 在服务器取到的数据进了 payload，浏览器水合时按 key 取用，不再请求，所以这两个各只调用 1 次。裸 `$fetch` 不知道 payload，浏览器水合时 setup 再执行一遍，又请求一次，所以一共 3 + 1 = 4 次，而且浏览器取到的数字和服务器渲染的不同，会出现水合不匹配。", "nuxt",
      "const raw = await $fetch('/api/count')\nconst { data: a } = await useFetch('/api/count')\nconst { data: b } = await useAsyncData('count-b', () => $fetch('/api/count'))"],
    ["下面的代码，用户直接在地址栏打开页面。服务器返回的 HTML 里，这个请求的 `status` 是什么，请求在哪里发出？", ["idle：服务器跳过请求，浏览器水合之后才发请求","success：服务器取了数据，放进 payload","pending：服务器一直等到请求完成才返回 HTML","error：服务器上不能发请求"], "`server: false` 让服务器不执行这个请求，所以 HTML 里 `status` 是 `idle`，数据是空的；浏览器水合之后才发请求。这适合不需要收录的数据。第二项是默认的 `useFetch`。第三项把它当成了“等待”，服务器根本没有发请求。", "nuxt",
      "const { data, status } = await useFetch('/api/count', { server: false })"],
    ["`app/middleware/log.global.ts` 在每次路由切换时打印一行并标明在哪一端。用户先直接在地址栏打开 `/products`，再点击页面里的链接进入 `/about`（浏览器内导航）。服务器终端和浏览器控制台各打印几行？", ["服务器 1 行（/products）；浏览器 2 行（/products、/about）","服务器 2 行（/products、/about）；浏览器 0 行","服务器 1 行（/products）；浏览器 1 行（/about）","服务器 2 行；浏览器 2 行"], "直接打开页面时，中间件先在服务器运行一次；浏览器水合时路由初始化，又在浏览器运行一次。之后点链接是浏览器内导航，只在浏览器运行，服务器不参与。所以服务器 1 行，浏览器 2 行。第三项漏了水合时浏览器上那一次。", "nuxt"],
    ["`nuxt.config.ts` 里有 `routeRules: { '/products': { prerender: true } }`，商品页用 `useFetch` 请求价格。部署之后，用户今天访问这个页面，价格是什么时候取到的？", ["构建时取到的，价格变了要重新构建部署才会更新","每个用户访问时，服务器重新取一次","第一个用户访问时取一次，之后缓存一小时","服务器不取，用户的浏览器在页面加载后取"], "`prerender: true` 在 `nuxt build` 时把页面渲染成 HTML 文件，`useFetch` 的结果在那时就取好并写进页面和 payload。之后的请求只是返回这个文件，不再渲染，也不再取数据。第三项是 `swr` 的行为，第四项是 `ssr: false` 的行为。", "nuxt"],
    ["Board 把任务数组 provide 给后代，后代 inject 后显示列表。useTasks 的 remove 用 filter 生成新数组并赋给 tasks.value。用户点击删除后，后代显示的列表会怎样？", ["仍显示被删除的任务：provide 的是当时的数组，remove 换成了新数组","被删除的任务消失，因为 provide / inject 是响应式的","后代组件报错，因为 inject 的数组被替换了","被删除的任务消失，但后代要重新挂载才能看到"], "provide('tasks', tasks.value) 传出去的是 .value 此刻指向的那个数组。remove 把 tasks.value 换成了新数组，后代手里仍是旧数组，所以任务还在。provide / inject 本身不是响应式的，传一个 ref（provide('tasks', tasks)）才能跟随 .value 的替换；或者像本章那样只 provide 操作函数，数据用 props 传。以为会自动更新的选项，把 provide 和 ref 的响应式混在一起了。", "project-board",
      "// Board 的 setup\nconst { tasks, remove } = useTasks()\nprovide('tasks', tasks.value)   // 后代：const tasks = inject('tasks')\n// remove(id) 里：tasks.value = tasks.value.filter(t => t.id !== id)"],
    ["卡片列表用 TransitionGroup，v-for 的 key 写成了下标。列表是 [A, B, C]，用户删除 B。哪一个 DOM 元素会播放离开动画？", ["显示 C 的那个元素：key 为 2 的元素被移除，B 那一行被复用并改成了 C","显示 B 的那个元素：它是被删除的任务","三个元素都播放离开动画","没有元素播放离开动画，因为下标不是稳定的 key"], "删除后新列表是 [A, C]，key 变成 0、1。key 为 0、1 的元素被复用（第二个元素的文字从 B 改成 C），key 为 2 的元素没有对应项，被移除并播放离开动画，它显示的是 C。用户看到的是最后一张卡片在淡出，而被删除的卡片瞬间消失。key 要用任务的 id，让元素和数据一一对应。以为是 B 的选项，假设了 Vue 按内容匹配元素。", "project-board",
      "<TransitionGroup tag=\"ul\" name=\"card\">\n  <TaskCard v-for=\"(t, i) in tasks\" :key=\"i\" :task=\"t\" />\n</TransitionGroup>"],
    ["看板的模板里，弹窗写成 <Teleport to=\"#modal-root\">，目标 <div id=\"modal-root\"> 写在同一个模板里的 Teleport 前面。打开弹窗（editing 为真）会怎样？", ["弹窗不显示，控制台警告找不到 Teleport 目标：挂载时这个 div 还没有插入文档","弹窗正常渲染在 #modal-root 里，因为目标在 Teleport 前面创建","弹窗渲染在原来的位置，Teleport 找不到目标时自动回退","整个看板挂载失败，页面空白"], "Teleport 在挂载时就按选择器去文档里找目标。同一个模板里的 div 此时刚创建，还没有被插入文档，document.querySelector 找不到它，Vue 警告 Failed to locate Teleport target，弹窗的内容不会渲染。目标要放在应用外面（例如 index.html 里的 #modal-root，或者直接用 body），或者给 Teleport 加 defer 属性（Vue 3.5），让它等应用挂载完再找。选项二、三以为 Vue 会兜底，选项四把警告当成了致命错误：看板其他部分照常显示。", "project-board",
      "<div>\n  <div id=\"modal-root\"></div>\n  <Teleport to=\"#modal-root\">\n    <div v-if=\"editing\" class=\"modal\">…</div>\n  </Teleport>\n</div>"],
    ["待办清单当前筛选是“未完成”，todos 是 [A（已完成）, B, C]。用户点击 B 行的“删除”（B 是列表里的第一行）。会删除哪一项？", ["A：i 是 visible 里的下标 0，而 splice 作用在 todos 上，下标 0 是 A","B：它是用户点击的那一行","A 和 B 都被删除","什么也不删，因为 visible 是 computed，不能修改"], "v-for 遍历的是 visible，i 是 B 在 visible 里的下标 0。splice(0, 1) 作用在 todos 上，todos 的下标 0 是 A。所以 A 被删了，页面上 B 还在。下标属于“这一份数组”，派生出来的列表和源数据的下标不对应。删除要按 id：todos.value = todos.value.filter(t => t.id !== id)。以为删除 B 的选项，把两份数组的下标当成了同一份。", "project-todo",
      "<li v-for=\"(todo, i) in visible\" :key=\"todo.id\">\n  {{ todo.text }}\n  <button @click=\"todos.splice(i, 1)\">删除</button>\n</li>"],
    ["用户上次删光了所有事项，localStorage 里保存的是 \"[]\"。下面哪种读取方式，会在刷新后错误地把示例数据放回来？", ["saved && saved.length ? saved : seed()","Array.isArray(saved) ? saved : seed()","saved ?? seed()","saved || seed()"], "这里 saved 是 JSON.parse 的结果（解析失败或没有数据时是 null）。空数组 [] 是用户的合法数据：“没有数据”和“数据是空的”是两件事。判断 length 把 [] 当成没有数据，示例事项又出现了。Array.isArray、?? 和 || 都只在 saved 不存在或不是数组时才回到示例数据（[] 在 JavaScript 里是真值）。", "project-todo",
      "const saved = JSON.parse(localStorage.getItem(KEY))   // 没有数据时是 null\nconst todos = ref(/* 读取方式 */)"],
    ["“全部”下有 [A（未完成）, B（已完成）]，下面的代码用 watch 维护 visible。用户把筛选切到“未完成”，然后勾选 A。页面上的列表会怎样？", ["A 仍显示在“未完成”列表里，因为勾选只改 done，不触发这个 watch","A 立刻消失，因为 done 变了","报错，watch 里不能给 ref 赋值","列表变空，因为 watch 重新运行时 todos 是空的"], "watch 的数据源是 [todos, filter]：todos 是 ref 数组，默认只在 .value 被替换时触发。勾选只改事项里的 done，既没有换数组，也没有改 filter，watch 不运行，visible 保持旧值。visible 是能从 todos 和 filter 算出来的派生数据，应该用 computed，它自动跟踪读到的所有属性。用 watch 手动同步派生数据，容易漏掉触发条件。", "project-todo",
      "const todos = ref([{ id: 1, text: 'A', done: false }, { id: 2, text: 'B', done: true }])\nconst filter = ref('all')\nconst visible = ref(todos.value)\nwatch([todos, filter], () => {\n  visible.value = filter.value === 'active' ? todos.value.filter(t => !t.done) : todos.value\n})"],
    ["下面的测试挂载一个顶层使用了 `await` 的组件（`async setup`），没有包 `Suspense`。`wrapper.text()` 是什么？", ["空字符串：组件需要 `Suspense` 边界才会渲染，`flushPromises` 也等不出内容","`你好，小明`：`flushPromises` 等到了 `await` 完成","`加载中`：Vue 自动显示回退内容","测试抛出异常，`mount` 失败"], "带 async setup 的组件必须放在 Suspense 里才会渲染。直接挂载时，`flushPromises` 之后 `text()` 和 `html()` 仍是空字符串（在 Vue Test Utils 2.5 与 Vue 3.5 上实测）。测试里要包一层 `Suspense`，再 `await flushPromises()`。Vue 不会自动显示回退内容，回退内容来自 `Suspense` 的 `fallback` 插槽。", "testing",
      "const AsyncUser = defineComponent({\n  async setup() {\n    const name = await Promise.resolve('小明')\n    return () => h('p', '你好，' + name)\n  },\n})\nconst wrapper = mount(AsyncUser)\nawait flushPromises()\nexpect(wrapper.text())"],
    ["store 用 `defineStore('cart', …)` 定义，导出的函数叫 `useCartStore`。要在测试里给它设置初始状态，`createTestingPinia` 的 `initialState` 怎么写？", ["`{ cart: { items: [...] } }`：键是 store 的 id","`{ useCartStore: { items: [...] } }`：键是导出的函数名","`{ items: [...] }`：直接写 state","`{ stores: { cart: { items: [...] } } }`"], "`initialState` 的键是 `defineStore` 的第一个参数，也就是 store 的 id，和导出的函数叫什么无关。直接写 state 会找不到对应的 store。", "testing"],
    ["测试用 MSW，`server.listen({ onUnhandledRequest: 'error' })`，只给 `/api/tasks` 写了处理器。组件还请求了 `/api/user`。会发生什么？", ["这个 `fetch` 失败（抛出错误），提醒你漏写了处理器","请求被悄悄放行，访问真实服务器","请求返回空的 200 响应","测试在启动时就整体失败，不会运行"], "`onUnhandledRequest: 'error'` 让没有处理器的请求失败：实测 `fetch` 抛出 `[MSW] Cannot bypass a request when using the \"error\" strategy`。这样不会偷偷访问真实网络，也不会让测试在没有数据的情况下误通过。", "testing"],
    ["一个项目的覆盖率是 100%，但有人为了凑覆盖率写了一批只 `mount` 组件、没有任何 `expect` 的测试。下面哪句话最准确？", ["覆盖率只说明这些行被运行过，不说明行为被验证过；这些组件改坏了测试也不会红","覆盖率 100% 说明所有行为都被验证过","没有 `expect` 的测试会让 Vitest 报错，所以不可能出现","覆盖率只统计有断言的行"], "覆盖率统计的是“代码被执行了”。没有断言的测试能执行代码却不检查结果，所以改坏实现它也不红。要用突变检验（故意改坏实现，看测试是否变红）确认测试有用。Vitest 不会因为没有断言而报错。", "testing"],
]
